/** @jsxImportSource preact */
// Pack-owned Live Call section screen (TSX edition): the operator's front-desk console.
// The current call rides the hero stage card; live captions, the final transcript, the
// answer/reject/hangup/speak controls, and the recent-calls list sit below it.
//
// Runtime contract (CustomScreenRuntime in the APP runtime): opaque-origin iframe;
// window.FormLogic is the only capability. All bridge logic lives in ./controller (a
// 1:1 behavioral port of the previous embedded-JS console); these components are pure
// renderers over its state.
//
// CRITICAL standby rule (the "connected but shows Simulate" bug class): presence
// 'remote' means a REAL desktop answers this line via the relay, so the standby panel
// is a mirror note ONLY and must NEVER offer the scripted demo call. Only 'none'/demo
// offers Simulate; 'local' shows no panel. See Standby below and the controller notes.
import { render } from 'preact';
import { useEffect, useMemo, useState } from 'preact/hooks';
import type { ConsoleController } from './controller';
import { createConsole, rec } from './controller';
import { ago, hhmm } from './phone';
import { CallStage, LiveCaptions } from './components/CallStage';
import { Transcript } from './components/Transcript';
import { RecentCalls } from './components/RecentCalls';

function PresencePill({ c }: { c: ConsoleController }) {
  const p = c.state.presence;
  if (c.state.connectionError) return <span id="presence" class="pill warn">Connection needs attention</span>;
  // While presence is still resolving, show a neutral "Connecting" pill rather than
  // "No desktop connected" — the desktop is usually just a beat behind on mount.
  if (!c.presenceSettled()) {
    return (
      <span id="presence" class="pill">
        <span class="spinner sm" aria-hidden="true" />
        Connecting...
      </span>
    );
  }
  let cls = 'pill warn';
  let label = 'OAIY not connected';
  if (p.kind === 'local') {
    cls = 'pill ok';
    label = 'Listening - OAIY on this computer';
  } else if (p.kind === 'remote') {
    cls = 'pill accent';
    label = 'Listening on ' + (p.deviceName || 'another machine') + ' - relay';
  } else if (c.offline()) {
    const seen = ago(c.state.linkedDesktop ? c.state.linkedDesktop.lastSeenAt : null);
    label = 'OAIY offline' + (seen ? ' - last seen ' + seen : '');
  } else if (c.isDemo()) {
    cls = 'pill';
    label = 'Demo bridge - simulated';
  }
  return (
    <span id="presence" class={cls}>
      <span class={'dot' + (p.kind !== 'none' ? ' live' : '')} />
      {label}
    </span>
  );
}

/** The between-calls surface: the last-call line plus the presence-branched panel.
 *  - remote: a REAL desktop is running (reachable via the relay). Mirror note only,
 *    NEVER the demo Simulate (a scripted call must never be offered when real
 *    hardware is live; that was the "connected but shows Simulate" bug).
 *  - none / demo: no real runtime at all, so offer the scripted demo call.
 *  - local: direct bridge, no panel. */
function Standby({ c }: { c: ConsoleController }) {
  const s = c.state;
  if (s.connectionError) return (
    <div class="standby"><div class="card callout" role="alert">
      <h2>Could not connect this screen</h2>
      <p class="note">{s.connectionError}</p>
      <p class="note">Open Device Setup to review the connection. An app owner may need to review the installed screen in App Studio.</p>
    </div></div>
  );
  // Still resolving presence on load: a loading spinner, never the Simulate card —
  // a desktop that's a beat behind must not flash the demo affordance.
  if (!c.presenceSettled()) {
    return (
      <div class="standby">
        <div class="card connecting">
          <span class="spinner" aria-hidden="true" />
          <p class="note">Connecting to the receptionist...</p>
        </div>
      </div>
    );
  }
  const last = s.recent.length > 0 ? s.recent[0] : null;
  let when: string | null = null;
  if (last) {
    const a = rec(last.answers);
    const startedAt = a.started_at;
    when = hhmm(typeof startedAt === 'string' && startedAt !== '' ? startedAt : last.submittedAt || '');
  }
  const line = c.remoteMode() ? 'Updates every 10s' : when ? 'Last call ' + when : 'Waiting for the next call';
  return (
    <div class="standby">
      <div class="faint">{line}</div>
      {s.presence.kind === 'remote' ? (
        <div class="card callout">
          <p class="note">
            {'The receptionist runs on ' + (s.presence.deviceName || 'another machine')
              + '. This console mirrors its calls and relays your controls.'}
          </p>
        </div>
      ) : c.offline() ? (
        // A real OAIY is linked but away: say when it was last seen and what it
        // keeps doing - never offer the scripted demo call over a real line.
        <div class="card callout warn" data-offline>
          <p class="note lead">
            <strong>
              {"OAIY can't be reached. " + (s.linkedDesktop ? s.linkedDesktop.deviceName : 'Your OAIY')
                + (ago(s.linkedDesktop ? s.linkedDesktop.lastSeenAt : null) ? ' was last seen ' + ago(s.linkedDesktop ? s.linkedDesktop.lastSeenAt : null) + '.' : ' has not been seen yet.')}
            </strong>
          </p>
          <p class="note">
            While it is away it keeps answering calls, lookups and appointment requests on that computer, and its call records reach this app when it reconnects. This console picks it up again by itself.
          </p>
        </div>
      ) : s.presence.kind !== 'local' ? (
        <div class="card">
          <p class="note lead">
            Connect OAIY in Device Setup to take real calls and keep your call records in this app. You can also explore with a scripted demo call.
          </p>
          <button type="button" class="btn" data-act="simulate" disabled={s.simulating}
            onClick={() => c.simulate()}>
            {s.simulating ? 'Simulating...' : 'Simulate incoming call'}
          </button>
        </div>
      ) : null}
    </div>
  );
}

function App() {
  const [, setVersion] = useState(0);
  const c = useMemo(() => createConsole(() => setVersion((v) => v + 1)), []);
  useEffect(() => c.wire(), [c]);
  const call = c.activeCall();
  return (
    <div id="lc" class="ak" aria-label="Live call console">
      <div class="console">
        <div class="chead">
          <div class="ident">
            <span class="logo" aria-hidden="true">A</span>
            <div>
              <h1>Aokie Receptionist</h1>
              <p class="sub">Front desk console</p>
            </div>
          </div>
          <PresencePill c={c} />
        </div>
        <div class="cbody">
          {(call === null || c.state.connectionError) && <Standby c={c} />}
          {call !== null && <CallStage c={c} call={call} />}
          {call !== null && <LiveCaptions call={call} captions={c.state.captions} />}
          <Transcript c={c} call={call} />
          <RecentCalls c={c} />
        </div>
      </div>
    </div>
  );
}

render(<App />, document.getElementById('root')!);

// Live Call console: state + bridge logic (no JSX). This is the behavioral core of the
// pack-owned operator console, ported 1:1 from the previous embedded-JS screen; every
// gating rule, connector payload, and user-facing string is preserved. Only the
// rendering mechanism changed: the preact components under ./components read `state`
// and re-render when `repaint` bumps (the old paint*() calls all map to repaint()).
//
// Load-bearing rules kept intact:
//  - the STANDBY panel branches by presence (rendered in index.tsx from this state):
//    'remote' means a REAL desktop is reachable via the relay, so the panel is a mirror
//    note ONLY and NEVER offers the scripted demo Simulate; 'none'/demo offers the demo
//    call via host.ceremony('simulate-call'); 'local' shows no panel at all;
//  - presence() is re-polled every tick: detection is demand-driven and may only finish
//    AFTER this screen mounts, so a late-connecting desktop self-heals here; the events
//    and captions lanes attach on a transition TO 'local' and detach when it goes away;
//  - command outcomes are surfaced honestly: 'uncertain' means the desktop may have
//    acted, and the operator is told exactly that.

import { ms, tail9 } from './phone';

/** How long to show the loading spinner while desktop presence is still resolving.
 *  Detection is demand-driven and warms AFTER mount, so the first presence() reads
 *  can be a transient 'none' even when a desktop is a beat away from connecting.
 *  We hold the spinner (instead of flashing the demo Simulate card) until presence
 *  settles to a real runtime, the demo account is confirmed, or this grace elapses —
 *  a genuinely absent desktop then shows the Install/Simulate card. Covers one full
 *  3s poll cycle plus headroom. */
export const PRESENCE_GRACE_MS = 4000;

/** The effective grace — a host/test may override it via window.__flPresenceGraceMs
 *  (the screen behavioral tests set 0 for steady-state assertions). */
function presenceGraceMs(): number {
  const w = typeof window !== 'undefined' ? (window as unknown as { __flPresenceGraceMs?: unknown }) : undefined;
  const o = w && typeof w.__flPresenceGraceMs === 'number' ? w.__flPresenceGraceMs : NaN;
  return Number.isFinite(o) ? (o as number) : PRESENCE_GRACE_MS;
}

/** The presence/call poll cadence — overridable via window.__flPollMs so the
 *  behavioral tests can drive multiple poll cycles without real 3s waits. */
function pollMs(): number {
  const w = typeof window !== 'undefined' ? (window as unknown as { __flPollMs?: unknown }) : undefined;
  const o = w && typeof w.__flPollMs === 'number' ? w.__flPollMs : NaN;
  return Number.isFinite(o) && (o as number) > 0 ? (o as number) : 3000;
}

/** Loose record view of an unknown value (the old rec() helper). */
export function rec(v: unknown): Record<string, unknown> {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {};
}

export interface CallInfo {
  callId: string | undefined;
  from?: string;
  callerName?: string;
  state: 'ringing' | 'active' | 'ended';
  startedAt?: string;
}

export interface Turn {
  key: string;
  speaker: string;
  text: string;
  occurredAt?: string;
  callId: string | undefined;
  turn: number | null;
  corrected?: boolean;
}

export interface ConsoleState {
  presence: FlPresence;
  connectionError: string | null;
  recentError: string | null;
  /** The viewer is the shared demo account (demo@formlogic.local). */
  demo: boolean;
  call: CallInfo | null;
  /** Live/derived transcript turns for the current call. */
  turns: Turn[];
  /**
   * Which call the stored-turns poll last looked for, so an empty conversation
   * can say WHY it is empty. "No transcript recorded" reads the same whether
   * the turns are missing, the call is unidentified, or the poll never ran —
   * three different faults wearing one sentence, which cost a long time to
   * tell apart from the outside.
   */
  turnsCallId: string | null;
  /** How many stored turns the last poll actually saw, across all calls. */
  turnsSeen: number;
  /** Why the last poll could not read them, if it could not. */
  turnsError: string | null;
  /** Volatile captions frame (caller partial + bot line + session phase). */
  captions: Record<string, unknown> | null;
  /** queryRecords('customers') cache for the known-caller name lookup. */
  customers: FlScreenRecord[];
  /** records() cache: the recent Calls rows. */
  recent: FlScreenRecord[];
  /** can() cache. */
  grants: Record<string, boolean>;
  speakText: string;
  pendingSpeak: string | null;
  busy: string | null;
  simulating: boolean;
  startedAtMs: number | null;
  /** events.subscribe attached (local bridge); else the stored-turns poll drives the transcript. */
  liveEvents: boolean;
  /** The owner's linked OAIY seen most recently (desktop.connections.list), for
   *  'last seen' while it is away. null = none linked, or a member (owner-only). */
  linkedDesktop: { deviceName: string; lastSeenAt: string | null } | null;
}

export interface ConsoleController {
  state: ConsoleState;
  isDemo(): boolean;
  remoteMode(): boolean;
  /** A linked OAIY exists but cannot be reached: the console says when it was
   *  last seen instead of offering the scripted demo call. */
  offline(): boolean;
  /** False only during the brief boot window while desktop presence is still
   *  resolving — the standby surface shows a loading spinner until this is true. */
  presenceSettled(): boolean;
  activeCall(): CallInfo | null;
  can(perm: string): boolean;
  nameForPhone(phone: unknown): string | null;
  callControl(command: 'call.answer' | 'call.reject' | 'call.hangup'): void;
  setSpeakText(v: string): void;
  sendSpeak(): Promise<void>;
  simulate(): void;
  viewAll(): void;
  openRecent(id: string): void;
  /** Boot + start the poll timers; returns the dispose function. */
  wire(): () => void;
}

export function createConsole(repaint: () => void): ConsoleController {
  const state: ConsoleState = {
    presence: { kind: 'none' },
    connectionError: null,
    recentError: null,
    demo: false,
    call: null,
    turns: [],
    turnsCallId: null,
    turnsSeen: 0,
    turnsError: null,
    captions: null,
    customers: [],
    recent: [],
    grants: {},
    speakText: '',
    pendingSpeak: null,
    busy: null,
    simulating: false,
    startedAtMs: null,
    liveEvents: false,
    linkedDesktop: null,
  };
  const caps: {
    unsubEvents: (() => Promise<unknown>) | null;
    capHandle: { unsubscribe(): Promise<unknown>; tombstone(): Promise<unknown> } | null;
  } = { unsubEvents: null, capHandle: null };
  let prevCallerTurns = 0;
  // When the console mounted — the presence grace is measured from here (0 until wired).
  let bootAtMs = 0;
  // Consecutive call.current polls that reported NO call while we still show a
  // live one — see setCallFromCurrent.
  let currentMisses = 0;

  const isDemo = () => state.presence.kind === 'none' && state.demo === true;
  const offline = () => state.presence.kind === 'none' && !state.demo && state.linkedDesktop !== null;
  const remoteMode = () => state.presence.kind === 'remote';
  // Settled once a real runtime is present, the demo account is confirmed, or the boot
  // grace has elapsed for a genuinely absent desktop. While unsettled the standby shows
  // a spinner instead of the demo Simulate card (avoids the "connecting" flash).
  const presenceSettled = () =>
    state.connectionError !== null ||
    state.presence.kind === 'local' ||
    state.presence.kind === 'remote' ||
    isDemo() ||
    (bootAtMs > 0 && Date.now() - bootAtMs >= presenceGraceMs());
  const activeCall = () => (state.call && state.call.state !== 'ended' ? state.call : null);
  const can = (perm: string) => !state.connectionError && state.grants[perm] === true;

  function nameForPhone(phone: unknown): string | null {
    const t = tail9(phone);
    if (t.length < 5) return null;
    for (let i = 0; i < state.customers.length; i++) {
      const a = rec(state.customers[i].answers);
      if (tail9(a.phone) === t) {
        const n = String(a.name == null ? '' : a.name).trim();
        return n || null;
      }
    }
    return null;
  }

  /** The old `e && e.message ? e.message : fallback` shape, typed. */
  function errMessage(e: unknown, fallback: string): string {
    if (e && typeof e === 'object') {
      const m = (e as { message?: unknown }).message;
      if (m) return String(m);
    }
    return fallback;
  }

  // ---- data ----------------------------------------------------------------

  function setCallFromCurrent(res: Record<string, unknown>): void {
    const c = rec(res.call);
    if (typeof c.callId === 'string') {
      currentMisses = 0;
      const st: CallInfo['state'] = c.state === 'active' ? 'active' : c.state === 'ended' ? 'ended' : 'ringing';
      const prev = state.call;
      const same = prev !== null && prev.callId === c.callId;
      state.call = {
        callId: c.callId,
        from: typeof c.from === 'string' ? c.from : (same ? prev.from : undefined),
        callerName: typeof c.callerName === 'string' ? c.callerName : undefined,
        state: st,
        startedAt: typeof c.startedAt === 'string' ? c.startedAt : (same ? prev.startedAt : undefined),
      };
      state.startedAtMs = ms(state.call.startedAt) || (same ? state.startedAtMs : Date.now());
    } else if (!state.call || state.call.state === 'ended') {
      currentMisses = 0;
      state.call = null;
      state.startedAtMs = null;
    } else {
      // The plugin is AUTHORITATIVE and reports no current call while the
      // stage still shows one as ringing/active: the ended event was missed
      // (the relay path has no event lane at all, and even the local lane can
      // shed a frame). Two consecutive misses (~2 poll cycles) end the call
      // here; a single miss is forgiven so an in-flight null response racing
      // a just-started call can never kill the fresh stage. Without this the
      // hangup button stuck forever (live report 2026-07-18).
      currentMisses += 1;
      if (currentMisses >= 2) {
        currentMisses = 0;
        state.call.state = 'ended';
        state.startedAtMs = null;
        setTimeout(() => { void refreshRecent().then(() => repaint()); }, 1500);
      }
    }
  }

  function refreshCall(): Promise<void> {
    if (!can('connector.aokie.call.current')) return Promise.resolve();
    return FormLogic.connector('aokie', 'call.current', {}).then((out) => {
      if (out.status === 'done') setCallFromCurrent(rec(out.result));
    }).catch(() => undefined);
  }

  function refreshRecent(): Promise<void> {
    return FormLogic.records({ limit: 8 }).then((rows) => {
      state.recent = rows || [];
      state.recentError = null;
    }).catch((err: unknown) => { state.recentError = errMessage(err, 'Could not load call records.'); });
  }

  function refreshCustomers(): Promise<void> {
    return FormLogic.queryRecords('customers', { limit: 200 }).then((rows) => {
      state.customers = rows || [];
    }).catch(() => undefined);
  }

  /** The newest STORED call's id, from the recent-calls poll (Calls rows come
   *  back newest-first). This is the call the 'Latest call' transcript belongs
   *  to when none is in progress. */
  function latestStoredCallId(): string | undefined {
    for (let i = 0; i < state.recent.length; i++) {
      const id = String(rec(state.recent[i].answers).call_id || '');
      if (id) return id;
    }
    return undefined;
  }

  /** Remote/demo transcript: stored Transcript Turns for the current call, or —
   *  when the plugin reports no current call — for the most recent stored one.
   *
   *  The fallback is the whole point of the 'Latest call' heading. On real
   *  hardware call.current goes null the moment a call ends, so keying this
   *  poll on the CURRENT call alone made every finished call unreadable: reload
   *  the page with no call in progress and the turns were written, stored and
   *  permitted, but never queried — "No transcript recorded for the latest call
   *  yet", permanently (live report 2026-08-01). */
  function refreshStoredTurns(): Promise<void> {
    if (state.liveEvents) return Promise.resolve();
    const callId = (state.call && state.call.callId) || latestStoredCallId();
    state.turnsCallId = callId || null;
    if (!callId) {
      state.turns = [];
      return Promise.resolve();
    }
    return FormLogic.queryRecords('transcript-turns', { limit: 60 }).then((rows) => {
      const list = rows || [];
      const out: Turn[] = [];
      for (let i = 0; i < list.length; i++) {
        const a = rec(list[i].answers);
        if (String(a.call_id || '') !== callId) continue;
        const idx = a.turn_index;
        out.push({
          key: list[i].id,
          speaker: typeof a.speaker === 'string' && a.speaker ? a.speaker : 'system',
          text: String(a.text == null ? '' : a.text),
          occurredAt: typeof a.timestamp === 'string' && a.timestamp ? a.timestamp : list[i].submittedAt,
          callId,
          turn: typeof idx === 'number' ? idx : (typeof idx === 'string' && idx !== '' && !isNaN(Number(idx)) ? Number(idx) : null),
          corrected: a.source === 'audio_model',
        });
      }
      out.sort((x, y) => {
        if (x.occurredAt && y.occurredAt && x.occurredAt !== y.occurredAt) return x.occurredAt < y.occurredAt ? -1 : 1;
        if (x.turn != null && y.turn != null && x.turn !== y.turn) return x.turn - y.turn;
        return 0;
      });
      state.turns = out;
      state.turnsSeen = list.length;
      state.turnsError = null;
    }).catch((e: unknown) => {
      // NOT swallowed. A read that failed and a call with nothing recorded are
      // different facts, and reporting them with one sentence is what made this
      // take so long: the card said "nothing stored yet" either way.
      state.turnsError = errMessage(e, 'the stored turns could not be read');
    });
  }

  // ---- live event lane (LOCAL bridge only) ---------------------------------

  function onEvent(frame: FlPushFrame): void {
    if (frame.kind === 'dropped') {
      void refreshCall();
      void refreshRecent();
      return;
    }
    const env = rec(frame.data);
    const data = rec(env.data);
    const callId = typeof data.callId === 'string' ? data.callId
      : (typeof env.correlationId === 'string' ? env.correlationId : undefined);
    switch (env.name) {
      case 'aokie.call.incoming':
        state.turns = [];
        state.call = {
          callId,
          from: typeof data.from === 'string' ? data.from
            : (typeof data.callerPhone === 'string' ? data.callerPhone : undefined),
          callerName: typeof data.callerName === 'string' ? data.callerName : undefined,
          state: 'ringing',
          startedAt: new Date().toISOString(),
        };
        state.startedAtMs = Date.now();
        break;
      case 'aokie.call.answered':
        if (state.call) state.call.state = 'active';
        break;
      case 'aokie.call.caller_id':
        if (state.call && state.call.callId === callId && !state.call.from && typeof data.from === 'string') {
          state.call.from = data.from;
        }
        break;
      case 'aokie.call.turn.final':
        state.turns = state.turns.slice(-49).concat([{
          key: typeof env.idempotencyKey === 'string' && env.idempotencyKey !== ''
            ? env.idempotencyKey
            : String(callId) + ':' + String(data.turn),
          speaker: typeof data.speaker === 'string' ? data.speaker : 'caller',
          text: typeof data.text === 'string' ? data.text : '',
          occurredAt: typeof env.occurredAt === 'string' ? env.occurredAt : undefined,
          callId,
          turn: typeof data.turn === 'number' ? data.turn : (Number(data.turn) || null),
        }]);
        break;
      case 'aokie.call.turn.corrected': {
        const tn = typeof data.turn === 'number' ? data.turn : Number(data.turn);
        const fixed = typeof data.text === 'string' ? data.text : '';
        if (fixed && isFinite(tn)) {
          state.turns = state.turns.map((t) => (t.callId === callId && t.turn === tn)
            ? { key: t.key, speaker: t.speaker, text: fixed, occurredAt: t.occurredAt, callId: t.callId, turn: t.turn, corrected: true }
            : t);
        }
        break;
      }
      case 'aokie.call.rejected':
      case 'aokie.call.ended':
        if (state.call && state.call.callId === callId) state.call.state = 'ended';
        setTimeout(() => { void refreshRecent().then(() => repaint()); }, 1500);
        break;
      default:
        return;
    }
    repaint();
  }

  function attachLiveLanes(): Promise<unknown> {
    // Idempotent: only the LOCAL bridge carries live feeds, and never subscribe twice.
    if (state.presence.kind !== 'local' || caps.unsubEvents) return Promise.resolve();
    const evP = FormLogic.events.subscribe({ connectorId: 'aokie' }, onEvent).then((h) => {
      caps.unsubEvents = h.unsubscribe;
      state.liveEvents = true;
    }).catch(() => { state.liveEvents = false; });
    const capP = FormLogic.captions.subscribe((frame) => {
      if (frame.kind === 'dropped') return;
      state.captions = rec(frame.data);
      repaint();
    }).then((h) => { caps.capHandle = h; }).catch(() => undefined);
    // The visible partial is tombstoned when a durable caller turn lands (final wins).
    return Promise.all([evP, capP]);
  }

  function detachLiveLanes(): void {
    if (caps.unsubEvents) {
      try { void caps.unsubEvents(); } catch { /* best effort */ }
      caps.unsubEvents = null;
    }
    if (caps.capHandle) {
      try { void caps.capHandle.unsubscribe(); } catch { /* best effort */ }
      caps.capHandle = null;
    }
    state.liveEvents = false;
    state.captions = null;
  }

  function maybeTombstone(): void {
    let n = 0;
    for (let i = 0; i < state.turns.length; i++) {
      if (state.turns[i].speaker === 'caller') n++;
    }
    if (n > prevCallerTurns && caps.capHandle && typeof caps.capHandle.tombstone === 'function') {
      void caps.capHandle.tombstone();
    }
    prevCallerTurns = n;
  }

  // ---- actions -------------------------------------------------------------

  /** `quiet` withholds the toast so the caller can explain the failure better. */
  function runCommand(
    command: string,
    payload?: Record<string, unknown>,
    quiet?: boolean
  ): Promise<boolean> {
    state.busy = command;
    repaint();
    return FormLogic.connector('aokie', command, payload || {})
      .then((out) => {
        if (out.status !== 'done') {
          let m = errMessage(out.error, out.status);
          if (out.status === 'uncertain') m = 'Sent, but the desktop has not confirmed it yet.';
          if (!quiet) void FormLogic.toast.error(m);
          return false;
        }
        return true;
      })
      .catch((e: unknown) => {
        if (!quiet) void FormLogic.toast.error(errMessage(e, 'Command failed'));
        return false;
      })
      .then((ok) => {
        state.busy = null;
        return ok;
      });
  }

  /**
   * Answer / reject / hang up.
   *
   * Remote mode has no event lane, so the stage only learns a call ended on the
   * next poll — and one miss is forgiven before it believes it. That leaves a
   * window, up to two poll cycles wide, where the call is over and the button
   * is still up. Pressing it then used to surface the plugin's raw refusal:
   * `Plugin { code: -32000, message: "callId ... is stale: there is no current
   * call", typed: Some("stale_call") }` — which is correct, and unreadable, and
   * blames the operator for a race they cannot see (live report 2026-08-01,
   * hung up four seconds after the call had ended).
   *
   * The plugin is authoritative about what is live, so a failure is answered by
   * asking it rather than by parsing its message: re-read the current call, and
   * if there is none, the call had simply already ended — say that plainly and
   * clear the stage. Any other failure keeps its own message.
   */
  function callControl(command: 'call.answer' | 'call.reject' | 'call.hangup'): void {
    const c = activeCall();
    if (!c) return;
    void runCommand(command, { callId: c.callId }, true)
      .then((ok) => (ok ? Promise.resolve(null) : pluginHasCall()).then((hasCall) => ({ ok, hasCall })))
      .then(({ ok, hasCall }) => {
        if (!ok) {
          if (hasCall === false) {
            // Two independent confirmations that the call is over: our control
            // was refused AND the plugin reports nothing live. That is not a
            // single racing null, which is what the miss-forgiveness exists to
            // survive, so the stage clears now instead of after another cycle.
            void FormLogic.toast.error('That call had already ended.');
            state.call = null;
            state.startedAtMs = null;
            currentMisses = 0;
            void refreshRecent();
          } else {
            void FormLogic.toast.error(`Could not ${VERB[command]} the call.`);
          }
        }
        return refreshCall();
      })
      .then(() => repaint());
  }

  /**
   * Does the plugin report ANY live call right now? `null` when it did not
   * answer — unknown is not the same as none, and must never clear the stage.
   */
  function pluginHasCall(): Promise<boolean | null> {
    if (!can('connector.aokie.call.current')) return Promise.resolve(null);
    return FormLogic.connector('aokie', 'call.current', {})
      .then((out) => (out.status === 'done' ? typeof rec(rec(out.result).call).callId === 'string' : null))
      .catch(() => null);
  }

  /** What a failed control was trying to do, for the operator's message. */
  const VERB: Record<string, string> = {
    'call.answer': 'answer',
    'call.reject': 'reject',
    'call.hangup': 'hang up',
  };

  function setSpeakText(v: string): void {
    state.speakText = v;
    repaint();
  }

  function sendSpeak(): Promise<void> {
    const c = activeCall();
    if (!c) return Promise.resolve();
    const text = String(state.speakText || '').trim();
    if (!text) return Promise.resolve();
    state.speakText = '';
    state.pendingSpeak = text;
    repaint();
    return runCommand('call.operatorSpeak', { callId: c.callId, text }).then((ok) => {
      state.pendingSpeak = null;
      if (!ok) state.speakText = text;
      repaint();
    });
  }

  function simulate(): void {
    if (state.connectionError || state.presence.kind !== 'none' || state.simulating) return;
    state.simulating = true;
    repaint();
    void FormLogic.host.ceremony('simulate-call')
      .catch((err: unknown) => {
        void FormLogic.toast.error(errMessage(err, 'Could not start the demo call'));
      })
      .then(() => {
        state.simulating = false;
        repaint();
      });
  }

  function viewAll(): void {
    // The attached form's own records table. NOT a host screen open by name: the
    // Calls SECTION screen IS this console, so that would just re-open it.
    // openRecords() is gated on the viewer being able to see the records.
    void FormLogic.openRecords().catch((e: unknown) => {
      void FormLogic.toast.error(errMessage(e, 'Records are not available.'));
    });
  }

  function openRecent(id: string): void {
    if (id) void FormLogic.host.openRecord('calls', id).catch(() => undefined);
  }

  // The owner's linked desktops, for 'last seen' while OAIY is away. Owner-only:
  // a member's refusal (or a host without the service lane) leaves it null.
  // Read at boot and when presence drops to 'none' - never on every tick.
  function refreshLinkedDesktop(): Promise<void> {
    const sdk = FormLogic as unknown as { service?: (op: string, input?: Record<string, unknown>) => Promise<FlServiceOutcome> };
    if (typeof sdk.service !== 'function') return Promise.resolve();
    return sdk.service('desktop.connections.list', {}).then((out) => {
      if (!out || out.status !== 'done') return;
      const list = rec(out.result).connections;
      let best: { deviceName: string; lastSeenAt: string | null } | null = null;
      let bestAt = -1;
      for (const row of Array.isArray(list) ? list : []) {
        const r = rec(row);
        const at = typeof r.lastSeenAt === 'string' ? r.lastSeenAt : '';
        const t = ms(at) || 0;
        if (best === null || t > bestAt) {
          best = { deviceName: typeof r.deviceName === 'string' && r.deviceName.trim() ? r.deviceName : 'OAIY', lastSeenAt: at || null };
          bestAt = t;
        }
      }
      state.linkedDesktop = best;
    }).catch(() => undefined);
  }

  // ---- grants + boot -------------------------------------------------------

  const GRANTS = ['call.current', 'call.answer', 'call.reject', 'call.hangup', 'call.operatorSpeak'];

  function loadGrants(): Promise<unknown> {
    return Promise.all(GRANTS.map((g) =>
      FormLogic.can('connector.aokie.' + g).then((ok) => {
        state.grants['connector.aokie.' + g] = ok === true;
      })
    ));
  }

  function tick(): Promise<void> {
    const recovering = state.connectionError !== null;
    // Re-resolve presence every tick: detection is demand-driven and may only
    // finish AFTER this screen mounts (navigating in from another page), so a
    // late-connecting desktop self-heals here instead of needing a full reload.
    return FormLogic.presence()
      .then((p) => {
        state.connectionError = null;
        const prev = state.presence.kind;
        state.presence = p || { kind: 'none' };
        if (state.presence.kind === 'none' && prev !== 'none') void refreshLinkedDesktop().then(() => repaint());
        if (state.presence.kind === 'local' && prev !== 'local') return attachLiveLanes();
        if (prev === 'local' && state.presence.kind !== 'local') detachLiveLanes();
        return undefined;
      })
      .catch((err: unknown) => {
        state.connectionError = errMessage(err, 'Could not check the OAIY connection.');
        state.presence = { kind: 'none' };
        detachLiveLanes();
      })
      .then(() => recovering && !state.connectionError ? loadGrants() : undefined)
      .then(() => refreshCall())
      .then(() => (state.liveEvents ? Promise.resolve() : refreshStoredTurns()))
      .then(() => {
        maybeTombstone();
        repaint();
      }).catch((err: unknown) => {
        state.connectionError = errMessage(err, 'Could not refresh the receptionist console.');
        repaint();
      });
  }

  function loadAll(): Promise<void> {
    return FormLogic.presence()
      .then((p) => { state.presence = p || { kind: 'none' }; state.connectionError = null; })
      .catch((err: unknown) => {
        state.presence = { kind: 'none' };
        state.connectionError = errMessage(err, 'Could not check the OAIY connection.');
      })
      .then(() => FormLogic.currentUser())
      .then((u) => { state.demo = !!(u && u.email === 'demo@formlogic.local'); })
      .catch(() => undefined)
      .then(() => loadGrants())
      .then(() => Promise.all([refreshCall(), refreshRecent(), refreshCustomers(), refreshLinkedDesktop()]))
      .then(() => attachLiveLanes())
      .then(() => (state.liveEvents ? Promise.resolve() : refreshStoredTurns()))
      .then(() => {
        maybeTombstone();
        repaint();
      }).catch((err: unknown) => {
        state.connectionError = errMessage(err, 'Could not load the receptionist console.');
        repaint();
      });
  }

  function wire(): () => void {
    bootAtMs = Date.now();
    void loadAll();
    // Presence + call poll every 3s; recent calls every 10s; the elapsed timer
    // repaints the stage every 1s while a call is up.
    const pollTimer = setInterval(() => { void tick(); }, pollMs());
    const recentTimer = setInterval(() => { void refreshRecent().then(() => repaint()); }, 10000);
    const elapsedTimer = setInterval(() => { if (activeCall()) repaint(); }, 1000);
    // One repaint exactly at grace-end so a genuinely absent desktop drops the spinner
    // for the Install/Simulate card on time (not only on the next 3s poll).
    const graceTimer = setTimeout(() => repaint(), presenceGraceMs());
    return () => {
      clearInterval(pollTimer);
      clearInterval(recentTimer);
      clearInterval(elapsedTimer);
      clearTimeout(graceTimer);
      detachLiveLanes();
    };
  }

  return {
    state,
    isDemo,
    offline,
    remoteMode,
    presenceSettled,
    activeCall,
    can,
    nameForPhone,
    callControl,
    setSpeakText,
    sendSpeak,
    simulate,
    viewAll,
    openRecent,
    wire,
  };
}

// Digit + time helpers for the Live Call console. Ported 1:1 from the previous
// embedded-JS screen: the digit scans are deliberately character checks (no regex)
// and the zone-less timestamp fixup matches the documented "YYYY-MM-DD HH:MM:SS is
// UTC on the wire" rule.

/** Every ASCII digit in the value, in order (character scan, no regex). */
export function digits(s: unknown): string {
  let out = '';
  const str = String(s == null ? '' : s);
  for (let i = 0; i < str.length; i++) {
    const c = str.charAt(i);
    if (c >= '0' && c <= '9') out += c;
  }
  return out;
}

/** Last-9-digit suffix: the phone-number match key used across the platform. */
export function tail9(s: unknown): string {
  const d = digits(s);
  return d.length > 9 ? d.slice(-9) : d;
}

/** Zone-less "YYYY-MM-DD HH:MM:SS" strings are UTC on the wire; tag them so
 *  Date.parse cannot read them as local wall-clock time. */
export function utcify(s: string): string {
  if (typeof s !== 'string') return s;
  if (s.length === 19 && s.charAt(4) === '-' && s.charAt(10) === ' ' && s.charAt(13) === ':') {
    return s.slice(0, 10) + 'T' + s.slice(11) + 'Z';
  }
  return s;
}

/** Epoch millis for a timestamp string, or null when unparseable. */
export function ms(s: string | null | undefined): number | null {
  const t = Date.parse(utcify(s || ''));
  return isNaN(t) ? null : t;
}

/** Local HH:MM:SS for a timestamp, or null when unparseable. */
export function clock(s: string | null | undefined): string | null {
  const t = ms(s);
  if (t === null) return null;
  return new Date(t).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
}

/** Local HH:MM for a timestamp, or null when unparseable. */
export function hhmm(s: string | null | undefined): string | null {
  const t = ms(s);
  if (t === null) return null;
  return new Date(t).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function pad(n: number): string {
  return n < 10 ? '0' + n : '' + n;
}

/** Elapsed-call formatting: M:SS, or H:MM:SS past the hour. */
export function dur(msSpan: number): string {
  const s = Math.max(0, Math.floor(msSpan / 1000));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  return h > 0 ? h + ':' + pad(m) + ':' + pad(sec) : pad(m) + ':' + pad(sec);
}

/** Coarse age for a stored timestamp ('just now', '12 min ago', '3 h ago'), or null. */
export function ago(s: string | null | undefined, now: number = Date.now()): string | null {
  const t = ms(s);
  if (t === null) return null;
  const sec = Math.max(0, Math.round((now - t) / 1000));
  if (sec < 90) return 'just now';
  if (sec < 3600) return Math.round(sec / 60) + ' min ago';
  if (sec < 172800) return Math.round(sec / 3600) + ' h ago';
  return Math.round(sec / 86400) + ' days ago';
}

/** @jsxImportSource preact */
// The call stage (hero card) + the volatile live-captions card. Rendered only while a
// call is up; every label, gating rule, and footer string matches the previous
// embedded-JS console.
import type { CallInfo, ConsoleController } from '../controller';
import { dur } from '../phone';

export function CallStage({ c, call }: { c: ConsoleController; call: CallInfo }) {
  const s = c.state;
  const ringing = call.state === 'ringing';
  const known = call.callerName || c.nameForPhone(call.from);
  const display = call.callerName || known || call.from || 'Unknown caller';
  const initial = display.trim().charAt(0).toUpperCase() || '?';
  const elapsed = s.startedAtMs !== null ? dur(Date.now() - s.startedAtMs) : null;
  const eyebrow = ringing ? 'Incoming call' : 'Call in progress' + (elapsed ? ' - ' + elapsed : '');

  const canAnswer = ringing && c.can('connector.aokie.call.answer') && s.busy === null;
  const canReject = ringing && c.can('connector.aokie.call.reject');
  const canHangup = c.can('connector.aokie.call.hangup') && s.busy === null;

  const foot = c.remoteMode()
    ? 'Commands run on ' + (s.presence.deviceName || 'the hosting desktop')
    : s.presence.kind === 'local'
      ? 'OAIY on this computer - direct bridge'
      : 'Simulated call - demo bridge';

  return (
    <section class={'stage' + (ringing ? ' ringing' : '')}>
      <div class="caller">
        <span class="avatar" aria-hidden="true">{initial}</span>
        <div class="cid">
          <p class={'eyebrow' + (ringing ? '' : ' live')}>{eyebrow}</p>
          <p class="cname">{display}</p>
          <p class="cphone mono">
            {call.from ? call.from : 'No caller id'}
            {!call.callerName && known ? <span class="known">Known customer</span> : null}
          </p>
        </div>
      </div>
      <div class="controls">
        {ringing && (
          <button type="button" class="btn answer" data-act="answer" disabled={!canAnswer}
            onClick={() => c.callControl('call.answer')}>
            {s.busy === 'call.answer' ? 'Answering...' : 'Answer'}
          </button>
        )}
        {canReject && (
          <button type="button" class="btn reject" data-act="reject" disabled={s.busy !== null}
            onClick={() => c.callControl('call.reject')}>
            {s.busy === 'call.reject' ? 'Rejecting...' : 'Reject'}
          </button>
        )}
        <button type="button" class="btn hangup" data-act="hangup" disabled={!canHangup}
          onClick={() => c.callControl('call.hangup')}>
          {s.busy === 'call.hangup' ? 'Hanging up...' : 'Hang up'}
        </button>
      </div>
      <div class="stagefoot">{foot}</div>
    </section>
  );
}

/** The volatile captions strip: caller partial (italic), the bot's spoken line, and the
 *  session phase. Only shown for the CURRENT call's frame, and only when it has content. */
export function LiveCaptions({ call, captions }: { call: CallInfo; captions: Record<string, unknown> | null }) {
  if (!captions) return null;
  if (captions.callId !== call.callId) return null;
  const partial = captions.partialText;
  const bot = captions.botText;
  const phaseRaw = captions.phase;
  if (!partial && !bot && !phaseRaw) return null;
  const phase = String(phaseRaw || 'listening');
  return (
    <div class="capcard">
      <div class="caphd"><span class="dot live" />{'Live - ' + phase}</div>
      {partial ? <p class="cappartial">{'"' + String(partial) + '..."'}</p> : null}
      {bot ? <p class="capbot"><span class="tag">Aokie</span>{String(bot)}</p> : null}
    </div>
  );
}

/** @jsxImportSource preact */
// The conversation card: final transcript turns (live event lane on the local bridge,
// or the stored-turns poll in remote/demo mode), the in-flight operator line, and the
// operator composer. Copy, gating, and the corrected-turn tooltip match the previous
// embedded-JS console.
import { useEffect, useRef } from 'preact/hooks';
import type { CallInfo, ConsoleController, Turn } from '../controller';
import { clock } from '../phone';

function turnMeta(speaker: string): { side: 'caller' | 'agent' | 'system'; label: string; initial: string } {
  if (speaker === 'caller') return { side: 'caller', label: 'Caller', initial: 'C' };
  if (speaker === 'operator') return { side: 'agent', label: 'You', initial: 'Y' };
  // A system note, e.g. OAIY stopping mid-call: said once, centred, never a bubble.
  if (speaker === 'system') return { side: 'system', label: 'Note', initial: '!' };
  return { side: 'agent', label: 'Receptionist', initial: 'R' };
}

/**
 * Why the conversation is empty, in remote mode.
 *
 * One sentence used to cover three different faults — no call identified, a
 * call with nothing stored yet, and a poll that never ran — which is a large
 * part of why this took so long to pin down from the outside. Naming the call
 * it searched for makes the next report answer itself.
 */
function emptyReason(s: { turnsCallId: string | null; turnsSeen: number; turnsError: string | null }): string {
  if (s.turnsError) return `The stored turns could not be read: ${s.turnsError}`;
  if (!s.turnsCallId) return 'No call to show a transcript for yet.';
  const call = `…${s.turnsCallId.slice(-6)}`;
  if (s.turnsSeen === 0) return `No stored turns are visible to this console (looking for ${call}).`;
  // Turns were readable and none of them belong to this call — a different
  // fault from having none at all, and the one worth naming precisely.
  return `Read ${s.turnsSeen} stored turns; none belong to the latest call (${call}).`;
}

function TurnBubble({ turn }: { turn: Turn }) {
  const mt = turnMeta(turn.speaker);
  const time = clock(turn.occurredAt);
  if (mt.side === 'system') {
    return (
      <div class="turn system" role="note">
        <p class="ttext">{(time ? time + ' - ' : '') + turn.text}</p>
      </div>
    );
  }
  return (
    <div class={'turn ' + mt.side}>
      <span class="tav" aria-hidden="true">{mt.initial}</span>
      <div class="tbody">
        <div class="twho">
          {mt.label}
          {time ? <span class="ttime mono">{time}</span> : null}
        </div>
        <p class="ttext" title={turn.corrected ? 'Corrected by the audio model' : undefined}>{turn.text}</p>
      </div>
    </div>
  );
}

export function Transcript({ c, call }: { c: ConsoleController; call: CallInfo | null }) {
  const s = c.state;
  const heading = call ? 'Conversation' : c.remoteMode() ? 'Latest call' : 'Last call';
  const turns = s.turns;
  const box = useRef<HTMLDivElement>(null);
  const lastKey = turns.length > 0 ? turns[turns.length - 1].key : '';
  // Keep the newest turn in view as the conversation grows. (The old screen pinned
  // the scroll on EVERY repaint; pinning only when the content changes lets the
  // operator scroll back through a long call without being yanked down.)
  useEffect(() => {
    if (box.current) box.current.scrollTop = box.current.scrollHeight;
  }, [turns.length, lastKey, s.pendingSpeak]);

  const reason = call
    ? call.state === 'ringing'
      ? 'Answer the call to speak'
      : !c.can('connector.aokie.call.operatorSpeak')
        ? 'Speaking is not granted to this app'
        : null
    : null;
  const disabled = reason !== null || s.busy !== null;

  return (
    <section class="card">
      <div class="thead"><h2>{heading}</h2></div>
      {turns.length === 0 && s.pendingSpeak === null ? (
        <p class="muted tempty">
          {c.remoteMode() ? emptyReason(s) : 'Final transcript turns stream in here during a call.'}
        </p>
      ) : (
        <div class="turns" ref={box}>
          {turns.map((t) => <TurnBubble key={t.key} turn={t} />)}
          {s.pendingSpeak !== null && (
            <div class="turn agent pending">
              <span class="tav" aria-hidden="true">Y</span>
              <div class="tbody">
                <div class="twho">You<span class="ttime">sending...</span></div>
                <p class="ttext">{s.pendingSpeak}</p>
              </div>
            </div>
          )}
        </div>
      )}
      {call !== null && (
        <div class="composer">
          <input
            id="speak"
            type="text"
            placeholder={reason || 'Speak to the caller as the operator...'}
            disabled={disabled}
            value={s.speakText}
            onInput={(e) => c.setSpeakText(e.currentTarget.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                void c.sendSpeak();
              }
            }}
          />
          <button type="button" class="send" id="send" data-act="send" aria-label="Send to caller"
            disabled={disabled} onClick={() => void c.sendSpeak()}>
            {'\u203A'}
          </button>
        </div>
      )}
    </section>
  );
}

