.ak *, .ak *::before, .ak *::after { box-sizing: border-box; }
.ak p { margin: 0; overflow-wrap: break-word; }
.ak p + p { margin-top: 8px; }

/* -- type ---------------------------------------------------------------- */
.ak .page-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 6px 12px; padding: 2px 2px 0; }
.ak h1 { margin: 0; font-size: 18px; font-weight: 650; letter-spacing: -0.015em; line-height: 1.25; }
.ak .page-head .sub { margin: 2px 0 0; flex-basis: 100%; font-size: 12.5px; color: var(--fl-muted); }
.ak h2 { margin: 0 0 10px; font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--fl-muted); }
.ak h3 { margin: 16px 0 6px; font-size: 12.5px; font-weight: 600; color: var(--fl-text); }
.ak .muted { color: var(--fl-muted); font-size: 12.5px; }
.ak .faint { color: var(--fl-faint); font-size: 12px; }
.ak .hint { display: block; margin: 5px 0 0; font-size: 11.5px; line-height: 1.5; color: var(--fl-faint); }
.ak .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; }
.ak strong { font-weight: 600; }

/* -- cards --------------------------------------------------------------- */
.ak .card { background: var(--fl-surface); border: 1px solid var(--fl-border); border-radius: 14px; padding: 16px 18px; box-shadow: var(--fl-shadow); min-width: 0; }
.ak .card > .muted:first-of-type { margin-bottom: 4px; }
.ak .hdr, .ak .sectionrow { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; margin-bottom: 10px; }
.ak .hdr h2, .ak .sectionrow h2 { margin: 0; }
.ak .actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 14px; }
.ak .divided { margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--fl-border); }
.ak .footnote { margin-top: 12px; }

/* -- buttons ------------------------------------------------------------- */
.ak .btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 34px; padding: 7px 14px; border-radius: 9px;
  border: 1px solid var(--fl-border); background: var(--fl-surface); color: var(--fl-text); font: inherit; font-size: 13px; font-weight: 600;
  line-height: 1.2; cursor: pointer; white-space: nowrap; text-decoration: none;
  transition: background 0.15s ease, border-color 0.15s ease, filter 0.15s ease, opacity 0.15s ease; }
.ak .btn:hover:not(:disabled) { background: var(--fl-surface-2); border-color: color-mix(in srgb, var(--fl-accent) 45%, var(--fl-border)); }
.ak .btn:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; }
.ak .btn:disabled, .ak .btn[disabled] { opacity: 0.5; cursor: not-allowed; }
.ak .btn.sm { min-height: 28px; padding: 4px 11px; font-size: 12px; border-radius: 8px; }
.ak .btn.primary { background: var(--fl-accent); border-color: var(--fl-accent); color: var(--fl-accent-contrast); }
.ak .btn.primary:hover:not(:disabled) { background: var(--fl-accent); border-color: var(--fl-accent); filter: brightness(1.07); }
.ak .btn.danger { color: var(--fl-bad); border-color: color-mix(in srgb, var(--fl-bad) 55%, var(--fl-border)); }
.ak .btn.danger:hover:not(:disabled) { background: color-mix(in srgb, var(--fl-bad) 8%, transparent); border-color: var(--fl-bad); }
.ak .btn.danger.solid { background: var(--fl-bad); border-color: var(--fl-bad); color: var(--fl-accent-contrast); }

/* -- pills and dots ------------------------------------------------------ */
.ak .pill { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; padding: 2px 10px; font-size: 11px; font-weight: 600;
  line-height: 1.6; white-space: nowrap; color: var(--fl-muted); background: var(--fl-surface-2); border: 1px solid var(--fl-border); }
.ak .pill.ok { color: var(--fl-good); border-color: color-mix(in srgb, var(--fl-good) 40%, transparent); background: color-mix(in srgb, var(--fl-good) 10%, transparent); }
.ak .pill.warn { color: var(--fl-warn); border-color: color-mix(in srgb, var(--fl-warn) 40%, transparent); background: color-mix(in srgb, var(--fl-warn) 10%, transparent); }
.ak .pill.bad { color: var(--fl-bad); border-color: color-mix(in srgb, var(--fl-bad) 40%, transparent); background: color-mix(in srgb, var(--fl-bad) 10%, transparent); }
.ak .pill.accent { color: var(--fl-accent); border-color: color-mix(in srgb, var(--fl-accent) 40%, transparent); background: color-mix(in srgb, var(--fl-accent) 10%, transparent); }
.ak .dot { display: inline-block; flex: none; width: 8px; height: 8px; border-radius: 999px; background: var(--fl-faint); }
.ak .dot.ok { background: var(--fl-good); }
.ak .dot.warn { background: var(--fl-warn); }
.ak .dot.bad { background: var(--fl-bad); }
.ak .dot.live { animation: ak-pulse 1.4s ease-in-out infinite; }

/* -- notices: what needs attention, and what to do next ------------------ */
.ak .notice { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-top: 12px; padding: 11px 14px; border-radius: 10px;
  border: 1px solid var(--fl-border); border-left: 3px solid var(--fl-accent); background: color-mix(in srgb, var(--fl-accent) 6%, var(--fl-surface));
  font-size: 12.5px; line-height: 1.5; color: var(--fl-text); }
.ak .notice > span, .ak .notice > strong { flex: 1 1 260px; min-width: 0; }
.ak .notice strong { display: block; flex-basis: 100%; }
.ak .notice .btn { flex: none; }
.ak .notice.ok { border-left-color: var(--fl-good); background: color-mix(in srgb, var(--fl-good) 7%, var(--fl-surface)); }
.ak .notice.warn { border-left-color: var(--fl-warn); background: color-mix(in srgb, var(--fl-warn) 8%, var(--fl-surface)); }
.ak .notice.bad { border-left-color: var(--fl-bad); background: color-mix(in srgb, var(--fl-bad) 7%, var(--fl-surface)); }
.ak .banner { border: 1px solid color-mix(in srgb, var(--fl-bad) 45%, var(--fl-border)); border-left: 3px solid var(--fl-bad); border-radius: 10px; padding: 10px 14px;
  font-size: 13px; color: var(--fl-bad); background: color-mix(in srgb, var(--fl-bad) 6%, var(--fl-surface)); overflow-wrap: break-word; }

/* -- facts: label / value rows ------------------------------------------ */
.ak dl.facts { margin: 4px 0 0; }
.ak dl.facts > div { display: grid; grid-template-columns: minmax(118px, 32%) minmax(0, 1fr); gap: 3px 14px; align-items: baseline;
  padding: 8px 0; border-top: 1px solid var(--fl-border); }
.ak dl.facts > div:first-child { border-top: 0; padding-top: 2px; }
.ak dl.facts dt { font-size: 12px; color: var(--fl-muted); }
.ak dl.facts dd { margin: 0; display: flex; align-items: center; gap: 7px; min-width: 0; font-size: 13px; font-weight: 500; overflow-wrap: anywhere; }
@media (max-width: 480px) {
  .ak dl.facts > div { grid-template-columns: minmax(0, 1fr); }
}

/* -- form controls ------------------------------------------------------- */
.ak label.f { display: block; margin: 14px 0 0; }
.ak label.f:first-child, .ak h2 + label.f { margin-top: 0; }
.ak .lbl { display: block; margin-bottom: 5px; font-size: 12px; font-weight: 600; color: var(--fl-text); }
.ak input[type="text"], .ak input[type="password"], .ak textarea, .ak select {
  width: 100%; max-width: 100%; font: inherit; font-size: 13.5px; color: var(--fl-text); background: var(--fl-bg);
  border: 1px solid var(--fl-border); border-radius: 9px; padding: 8px 12px; min-height: 36px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease; }
.ak input[type="text"]:focus, .ak input[type="password"]:focus, .ak textarea:focus, .ak select:focus {
  outline: none; border-color: var(--fl-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--fl-accent) 18%, transparent); }
.ak input::placeholder, .ak textarea::placeholder { color: var(--fl-faint); }
.ak textarea { resize: vertical; min-height: 84px; line-height: 1.5; }
.ak select { cursor: pointer; }
.ak select option { background: var(--fl-bg); color: var(--fl-text); }
.ak input[type="checkbox"], .ak input[type="radio"] { accent-color: var(--fl-accent); }
.ak .chk { display: flex; align-items: flex-start; gap: 10px; margin: 12px 0 0; font-size: 13px; font-weight: 500; cursor: pointer; }
.ak .chk input { margin-top: 2px; width: 16px; height: 16px; flex: none; }
.ak .chk .sub { display: block; margin-top: 2px; font-size: 11.5px; font-weight: 400; color: var(--fl-faint); line-height: 1.5; }
.ak .chk.off { opacity: 0.55; cursor: not-allowed; }

/* -- choice cards (radio) ------------------------------------------------ */
.ak .choice { display: flex; align-items: flex-start; gap: 12px; margin-top: 8px; padding: 12px 14px; border: 1px solid var(--fl-border);
  border-radius: 12px; background: var(--fl-surface); cursor: pointer; transition: border-color 0.15s ease, background 0.15s ease; }
.ak .choice:hover { border-color: color-mix(in srgb, var(--fl-accent) 45%, var(--fl-border)); }
.ak .choice.on { border-color: var(--fl-accent); background: color-mix(in srgb, var(--fl-accent) 6%, var(--fl-surface)); }
.ak .choice input { margin-top: 3px; width: 16px; height: 16px; flex: none; }
.ak .choice-body { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.ak .choice-title { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 13.5px; font-weight: 600; }
.ak .choice-sub { font-size: 12px; line-height: 1.5; color: var(--fl-muted); }

/* -- disclosures --------------------------------------------------------- */
.ak details > summary { display: inline-flex; align-items: center; gap: 7px; cursor: pointer; list-style: none; font-size: 12.5px; font-weight: 600; color: var(--fl-muted); }
.ak details > summary::-webkit-details-marker { display: none; }
.ak details > summary::before { content: ''; width: 6px; height: 6px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
  transform: rotate(-45deg); transition: transform 0.15s ease; }
.ak details[open] > summary::before { transform: rotate(45deg); }
.ak details > summary:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; border-radius: 6px; }
.ak details > summary:hover { color: var(--fl-text); }

/* -- tables and lists ---------------------------------------------------- */
.ak .tscroll { overflow-x: auto; }
.ak table { width: 100%; border-collapse: collapse; font-size: 13px; }
.ak th { text-align: left; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: var(--fl-faint); padding: 0 12px 8px 0; }
.ak td { padding: 10px 12px 10px 0; border-top: 1px solid var(--fl-border); vertical-align: middle; }
.ak th:last-child, .ak td:last-child { padding-right: 0; }

/* -- empty and loading states -------------------------------------------- */
.ak .empty { padding: 14px 0 4px; }
.ak .empty-title { margin: 0 0 3px; font-size: 13.5px; font-weight: 600; color: var(--fl-muted); }
.ak .skeleton { display: block; height: 12px; width: 62%; border-radius: 999px; background: var(--fl-track); animation: ak-pulse 1.4s ease-in-out infinite; }
.ak .skeleton + .skeleton { margin-top: 9px; }
.ak .skeleton.short { width: 38%; }
.ak .spinner { width: 18px; height: 18px; flex: none; border-radius: 999px; border: 2px solid var(--fl-track); border-top-color: var(--fl-accent); animation: ak-spin 0.7s linear infinite; }
.ak .spinner.sm { width: 11px; height: 11px; }
@keyframes ak-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
@keyframes ak-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
  .ak .skeleton, .ak .spinner, .ak .dot.live { animation: none; }
}

/* -- the OAIY mark ------------------------------------------------------- */
.ak .mark { width: 34px; height: 34px; flex: none; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center;
  font-size: 15px; font-weight: 700; color: var(--fl-accent-contrast); background: var(--fl-accent); }

/* Live Call console - layout on top of the shared aokie.css (cards, buttons,
   pills, dots and spinners live there). One bordered shell; the call stage is
   the hero card; transcript bubbles and the recent-calls list follow the
   shared card pattern. Token-only. */
html, body { background: transparent; }
body { margin: 0; color: var(--fl-text); }

#lc { max-width: 840px; margin: 0 auto; padding: 14px 16px 24px; }
#lc .console { border: 1px solid var(--fl-border); border-radius: 18px; overflow: hidden; background: var(--fl-surface); box-shadow: var(--fl-shadow); }

#lc .chead { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px;
  padding: 14px 18px; border-bottom: 1px solid var(--fl-border); background: var(--fl-surface-2); }
#lc .ident { display: flex; align-items: center; gap: 12px; min-width: 0; }
#lc .logo { width: 38px; height: 38px; border-radius: 11px; flex: none; display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 15px; color: var(--fl-accent-contrast); background: var(--fl-accent); }
#lc h1 { font-size: 16px; }
#lc .sub { margin: 1px 0 0; font-size: 12px; color: var(--fl-faint); }
#lc #presence { padding: 4px 12px; }
#lc #presence .dot { background: currentColor; }

#lc .cbody { padding: 16px 18px; display: flex; flex-direction: column; gap: 14px; }
#lc .card { box-shadow: none; }
/* The standby wrapper's children join .cbody's flex flow directly. */
#lc .standby { display: contents; }
#lc .standby > .faint { padding: 2px 4px 0; }
/* Callouts: accent rail on a tinted surface; warn for an unreachable OAIY. */
#lc .card.callout { border-left: 3px solid var(--fl-accent); background: color-mix(in srgb, var(--fl-accent) 5%, var(--fl-surface)); }
#lc .card.callout.warn { border-left-color: var(--fl-warn); background: color-mix(in srgb, var(--fl-warn) 7%, var(--fl-surface)); }
#lc .note { font-size: 13px; line-height: 1.55; color: var(--fl-muted); }
#lc .note strong { color: var(--fl-text); }
#lc .note.lead { margin: 0 0 10px; }
#lc .tempty { font-size: 13px; }
#lc .card.connecting { display: flex; align-items: center; gap: 12px; }

/* The call stage. */
#lc .stage { border: 1px solid var(--fl-accent); border-radius: 16px; padding: 18px; background: color-mix(in srgb, var(--fl-accent) 4%, var(--fl-surface)); }
#lc .stage.ringing { animation: lc-ring 1.6s ease-in-out infinite; }
@keyframes lc-ring { 0%, 100% { box-shadow: 0 0 0 0 transparent; } 50% { box-shadow: 0 0 0 5px var(--fl-track); } }
#lc .caller { display: flex; align-items: center; gap: 14px; }
#lc .avatar { width: 48px; height: 48px; flex: none; border-radius: 999px; display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 16px; color: var(--fl-accent-contrast); background: var(--fl-accent); }
#lc .cid { min-width: 0; flex: 1; }
#lc .eyebrow { margin: 0; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--fl-accent); }
#lc .eyebrow.live { color: var(--fl-good); }
#lc .cname { margin: 2px 0 0; font-size: 19px; font-weight: 650; letter-spacing: -0.01em; overflow-wrap: break-word; }
#lc .cphone { margin: 2px 0 0; color: var(--fl-muted); }
#lc .known { display: inline-block; margin-left: 6px; border-radius: 999px; padding: 1px 8px; font-size: 11px; font-weight: 600;
  color: var(--fl-accent); background: color-mix(in srgb, var(--fl-accent) 10%, transparent); }
#lc .controls { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
#lc .controls .btn { min-height: 38px; padding: 8px 18px; }
#lc .btn.answer { background: var(--fl-accent); border-color: var(--fl-accent); color: var(--fl-accent-contrast); }
#lc .btn.reject { color: var(--fl-warn); border-color: color-mix(in srgb, var(--fl-warn) 55%, var(--fl-border)); }
#lc .btn.hangup { color: var(--fl-bad); border-color: color-mix(in srgb, var(--fl-bad) 55%, var(--fl-border)); }
#lc .stagefoot { margin-top: 14px; padding-top: 10px; border-top: 1px solid var(--fl-border); font-size: 12px; color: var(--fl-faint); }

/* Live captions. */
#lc .capcard { border: 1px solid var(--fl-border); border-radius: 14px; padding: 12px 18px; background: var(--fl-surface); }
#lc .caphd { display: flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--fl-faint); }
#lc .cappartial { margin: 6px 0 0; font-size: 14px; font-style: italic; color: var(--fl-muted); }
#lc .capbot { margin: 6px 0 0; font-size: 14px; color: var(--fl-good); }
#lc .capbot .tag { margin-right: 6px; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.07em; opacity: 0.75; }

/* Transcript. */
#lc .thead { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 12px; }
#lc .thead h2 { margin: 0; }
#lc .turns { display: flex; flex-direction: column; gap: 10px; max-height: 380px; overflow-y: auto; }
#lc .turn { display: flex; align-items: flex-start; gap: 8px; max-width: 86%; }
#lc .turn.caller { flex-direction: row-reverse; align-self: flex-end; }
#lc .turn.system { align-self: center; max-width: 92%; }
#lc .turn.system .ttext { border-radius: 10px; border-color: color-mix(in srgb, var(--fl-warn) 45%, var(--fl-border));
  background: color-mix(in srgb, var(--fl-warn) 8%, var(--fl-surface)); color: var(--fl-text); font-size: 12.5px; text-align: center; }
#lc .tav { width: 28px; height: 28px; flex: none; margin-top: 2px; border-radius: 999px; display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 700; background: var(--fl-track); color: var(--fl-muted); }
#lc .turn.agent .tav { background: var(--fl-accent); color: var(--fl-accent-contrast); }
#lc .turn.caller .tav { background: var(--fl-surface-2); color: var(--fl-muted); }
#lc .tbody { min-width: 0; }
#lc .twho { display: flex; align-items: baseline; gap: 8px; font-size: 11.5px; font-weight: 600; }
#lc .turn.caller .twho { flex-direction: row-reverse; }
#lc .ttime { font-size: 10.5px; font-weight: 400; color: var(--fl-faint); }
#lc .ttext { margin: 4px 0 0; padding: 9px 13px; font-size: 13.5px; line-height: 1.5; color: var(--fl-text);
  border: 1px solid var(--fl-border); white-space: pre-wrap; overflow-wrap: break-word; }
#lc .turn.agent .ttext { border-radius: 4px 14px 14px 14px; background: var(--fl-surface-2); }
#lc .turn.caller .ttext { border-radius: 14px 4px 14px 14px; background: var(--fl-surface); }
#lc .turn.pending .ttext { font-style: italic; opacity: 0.75; }

#lc .composer { display: flex; align-items: center; gap: 8px; margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--fl-border); }
#lc .composer input { flex: 1; min-width: 0; font: inherit; font-size: 13.5px; color: var(--fl-text);
  background: var(--fl-bg); border: 1px solid var(--fl-border); border-radius: 999px; padding: 9px 16px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease; }
#lc .composer input:focus-visible { outline: none; border-color: var(--fl-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--fl-accent) 18%, transparent); }
#lc .composer input:disabled { opacity: 0.5; }
#lc .send { width: 38px; height: 38px; flex: none; border-radius: 999px; cursor: pointer; border: 0;
  color: var(--fl-accent-contrast); background: var(--fl-accent); display: flex; align-items: center; justify-content: center; font-weight: 700; }
#lc .send:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; }
#lc .send[disabled] { opacity: 0.45; cursor: not-allowed; }

/* Recent calls. */
#lc ul.calls { list-style: none; margin: 0; padding: 0; }
#lc ul.calls li { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px;
  padding: 10px 8px; margin: 0 -8px; border-top: 1px solid var(--fl-border); border-radius: 8px; cursor: pointer; transition: background 0.12s ease; }
#lc ul.calls li:first-child { border-top: 0; }
#lc ul.calls li:hover { background: var(--fl-surface-2); }
#lc ul.calls li:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: -2px; }
#lc .cwho { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; min-width: 0; }
#lc .cwho-name { font-weight: 600; }
#lc .cstat { border-radius: 999px; padding: 2px 10px; font-size: 11px; font-weight: 600; text-transform: capitalize; color: var(--fl-muted); background: var(--fl-surface-2); }
#lc .cstat.ok { color: var(--fl-good); background: color-mix(in srgb, var(--fl-good) 10%, transparent); }
#lc .cstat.bad { color: var(--fl-bad); background: color-mix(in srgb, var(--fl-bad) 10%, transparent); }
#lc .link { color: var(--fl-accent); font-size: 12.5px; font-weight: 600; cursor: pointer; }
#lc .link:hover { text-decoration: underline; }
#lc .link:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; border-radius: 6px; }

/* Small phones: tighter shell, full-width call controls, wider bubbles. */
@media (max-width: 420px) {
  #lc { padding: 8px; }
  #lc .chead { padding: 12px 14px; }
  #lc .cbody { padding: 12px; gap: 12px; }
  #lc .card { padding: 13px; }
  #lc .stage { padding: 14px; }
  #lc .controls .btn { flex: 1 1 auto; }
  #lc .turn { max-width: 94%; }
}

/** @jsxImportSource preact */
// Pack-owned Calls transcript record screen — TSX edition (bundled in the sandbox on Preact).
//
// Runtime contract (CustomScreenRuntime + RecordScreenPanel):
//  - runs in an opaque-origin iframe (sandbox="allow-scripts", strict CSP, no network);
//  - `window.FormLogic` is the only bridge: this screen uses `related()` (the record's
//    related-record groups) — a record()-class TRUSTED_ONLY action, so the form's
//    custom_screen_trust must be owner/verified;
//  - theme comes from the injected `--fl-*` CSS variables and the `fl-dark` root class,
//    so light/dark both work with token-only styling;
//  - JSX text is auto-escaped, so record values can never inject markup.
import { render } from 'preact';
import { useEffect, useState } from 'preact/hooks';
import { compareTurns } from './sort';

/** Turns rendered per "Load more" click; the full set stays in memory so a long call
 *  does not paint hundreds of bubbles up front. */
const TURN_PAGE = 30;
/** The related endpoint's match-join cap: a group at exactly this size is almost
 *  certainly truncated to the newest turns. */
const SERVER_TURN_CAP = 500;

interface Turn {
  id: string;
  speaker: string;
  text: string;
  turnIndex: number | null;
  spokenAt: string | null;
  submittedAt?: string;
  /** The audio model re-heard and corrected this line (source=audio_model). */
  corrected: boolean;
}

interface RelatedGroup {
  fieldId?: string;
  columns?: Array<{ id: string; label?: string }>;
  records?: Array<{ id: string; fields: Record<string, unknown>; submittedAt?: string }>;
}

function toTurn(r: { id: string; fields: Record<string, unknown>; submittedAt?: string }): Turn {
  const f = r.fields || {};
  const idx = f.turn_index;
  const turnIndex = typeof idx === 'number' ? idx
    : (typeof idx === 'string' && idx !== '' && !isNaN(Number(idx)) ? Number(idx) : null);
  return {
    id: r.id,
    speaker: typeof f.speaker === 'string' && f.speaker ? f.speaker : 'system',
    text: typeof f.text === 'string' ? f.text : String(f.text == null ? '' : f.text),
    turnIndex,
    spokenAt: typeof f.timestamp === 'string' && f.timestamp !== '' ? f.timestamp : null,
    submittedAt: r.submittedAt,
    corrected: f.source === 'audio_model',
  };
}

/** Caller sits right and neutral; the receptionist (OAIY's Front desk agent or
 *  Aokie, or the operator standing in for it) sits left in the app accent; a
 *  system note (OAIY stopped answering, say) sits centred across the thread. */
function speakerMeta(speaker: string): { label: string; side: 'caller' | 'agent' | 'system'; initial: string } {
  if (speaker === 'caller') return { label: 'Caller', side: 'caller', initial: 'C' };
  if (speaker === 'operator') return { label: 'You', side: 'agent', initial: 'Y' };
  if (speaker === 'system') return { label: 'Note', side: 'system', initial: '!' };
  return { label: 'Receptionist', side: 'agent', initial: 'R' };
}

/** Several forms link to Calls through a field named call_link (follow-up tasks do too),
 *  so a fieldId match alone can pick the wrong group — require the group to actually
 *  carry transcript turns (speaker + text). */
function looksLikeTurns(g: RelatedGroup): boolean {
  const cols = g.columns || [];
  const hasCol = (id: string) => cols.some((c) => c.id === id);
  if (hasCol('speaker') && hasCol('text')) return true;
  const f = g.records && g.records[0] && g.records[0].fields;
  return !!f && 'speaker' in f && 'text' in f;
}

function Bubble({ turn }: { turn: Turn }) {
  const who = speakerMeta(turn.speaker);
  if (who.side === 'system') {
    return (
      <div class="turn system" role="note">
        <p class="text">{turn.text}</p>
      </div>
    );
  }
  return (
    <div class={`turn ${who.side}`}>
      <span class="avatar" aria-hidden="true">{who.initial}</span>
      <div class="bubble">
        <span class="who">
          {who.label}
          {turn.corrected && (
            <span class="corrected" title="Corrected by the audio model">corrected</span>
          )}
        </span>
        <p class="text">{turn.text}</p>
      </div>
    </div>
  );
}

function Transcript() {
  const [turns, setTurns] = useState<Turn[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [visible, setVisible] = useState(TURN_PAGE);

  useEffect(() => {
    FormLogic.related()
      .then((related) => {
        const groups = Object.values(related || {}) as RelatedGroup[];
        const group = groups.find((g) => g && g.fieldId === 'call_link' && looksLikeTurns(g)) || null;
        const rows = ((group && group.records) || []).map(toTurn);
        rows.sort(compareTurns);
        setTurns(rows);
      })
      .catch((e: unknown) => {
        setError((e instanceof Error && e.message) || 'Failed to load the transcript');
      });
  }, []);

  if (error) return <p class="state error">{error}</p>;
  if (turns === null) {
    return (
      <div role="status" aria-label="Loading transcript">
        <div class="skeleton" />
        <div class="skeleton right" />
        <div class="skeleton" />
      </div>
    );
  }
  if (turns.length === 0) {
    return <p class="state">No transcript was recorded for this call.</p>;
  }

  const shown = turns.slice(0, visible);
  const remaining = turns.length - shown.length;
  return (
    <div class="wrap">
      <div class="meta">
        <span class="count">{turns.length === 1 ? '1 turn' : `${turns.length} turns`}</span>
        {turns.length >= SERVER_TURN_CAP && <span class="note">showing the most recent turns</span>}
      </div>
      <div class="turns">
        {shown.map((t) => <Bubble key={t.id} turn={t} />)}
        {remaining > 0 && (
          <button type="button" class="more" onClick={() => setVisible(visible + TURN_PAGE)}>
            Load more ({remaining} more {remaining === 1 ? 'turn' : 'turns'})
          </button>
        )}
      </div>
    </div>
  );
}

// .ak: the shared Aokie stylesheet (aokie.css) scopes its tokens to it.
const rootEl = document.getElementById('root')!;
rootEl.classList.add('ak');
render(<Transcript />, rootEl);

/**
 * True conversation order for transcript turns — the SAME rule the compiled screen used:
 *  1. `spokenAt` (the plugin's speech-START stamp, ISO-8601 UTC — string compare is
 *     chronological): a caller line spoken OVER a bot reply sorts where it was SAID,
 *     not where it was committed;
 *  2. `turnIndex` orders rows from older plugins that predate the timestamp;
 *  3. `submittedAt` breaks the remaining ties.
 *
 * This file ships INSIDE the sandboxed screen (customScreen.files) and is ALSO imported
 * directly by the pack unit tests — the tested function IS the shipped code.
 */
export interface TurnOrderKeys {
  spokenAt?: string | null;
  turnIndex?: number | null;
  submittedAt?: string | null;
}

export function compareTurns(a: TurnOrderKeys, b: TurnOrderKeys): number {
  if (a.spokenAt && b.spokenAt && a.spokenAt !== b.spokenAt) return a.spokenAt.localeCompare(b.spokenAt);
  if (a.turnIndex != null && b.turnIndex != null && a.turnIndex !== b.turnIndex) return a.turnIndex - b.turnIndex;
  return String(a.submittedAt || '').localeCompare(String(b.submittedAt || ''));
}

