/** @jsxImportSource preact */
// Pack-owned Receptionist Settings SECTION screen - TSX edition (bundled in
// the sandbox on Preact). The grouped-card console over the singleton
// Receptionist Settings record PLUS the live plugin settings.
//
// Runtime contract (CustomScreenRuntime, APP runtime):
//  - opaque-origin iframe, strict CSP; `window.FormLogic` is the only bridge.
//    Lanes used: connector('aokie','settings.get'/'.set') (local-or-relay is
//    transparent), records()/submit()/updateRecord() (the singleton record -
//    create-on-first-save, then PARTIAL patches the controller PATCH-merges),
//    aiSources(), presence(), can(). Every action is TRUSTED_ONLY: the form's
//    custom_screen_trust must be owner/verified.
//  - The manager-PIN security boundary lives ENTIRELY in the plugin
//    (settings.get never returns the PIN - only managerPinSet; settings.set
//    seals + redacts + validates it): this screen can only WRITE a new PIN
//    and can never read the stored one. See store.ts for the preserved
//    write-only / partial-save / create-guard invariants.
//  - Theme = the injected --fl-* variables; JSX text is auto-escaped, so
//    record/settings values can never inject markup.
//  - The OAIY route (call_route 'oaiy', the default for new records) leads:
//    the OAIY card says whether OAIY is reachable and where calls go, the
//    route card chooses, and the voice / speech / audio cards give way to a
//    "Set in OAIY" card (OAIY owns those on its route).
import { render } from 'preact';
import { useEffect, useState } from 'preact/hooks';
import { loadAll, onOaiy, state, subscribe } from './store';
import { OaiyCard } from './components/OaiyCard';
import { RunningCard } from './components/RunningCard';
import { RouteCard } from './components/RouteCard';
import { BusinessCard } from './components/BusinessCard';
import { PersonalityCard } from './components/PersonalityCard';
import { SetInOaiyCard } from './components/SetInOaiyCard';
import { VoiceCard } from './components/VoiceCard';
import { ServicesCard } from './components/ServicesCard';
import { BackgroundAiCard } from './components/BackgroundAiCard';
import { AudioCard } from './components/AudioCard';
import { WaitingCard } from './components/WaitingCard';
import { ScreeningCard } from './components/ScreeningCard';
import { AdvancedCard } from './components/AdvancedCard';
import { SaveBar } from './components/SaveBar';

function Loading() {
  return (
    <section class="card" aria-busy="true" aria-label="Loading settings">
      <span class="skeleton" />
      <span class="skeleton short" />
      <p class="muted">Loading the receptionist settings...</p>
    </section>
  );
}

function App() {
  const [, setTick] = useState(0);
  useEffect(() => subscribe(() => setTick((t) => t + 1)), []);
  const toOaiy = onOaiy();
  return (
    <div id="rs" class="ak" aria-label="Receptionist settings">
      <header class="page-head">
        <h1>Receptionist settings</h1>
        <p class="sub">How the Aokie receptionist answers your phone, and what FormLogic sends it.</p>
      </header>
      <div id="cards">
        {state.draft === null ? (
          <Loading />
        ) : (
          <>
            <OaiyCard />
            {state.err ? <div id="err" role="alert">{state.err}</div> : null}
            <RunningCard />
            <RouteCard />
            <BusinessCard />
            <PersonalityCard />
            {toOaiy ? <SetInOaiyCard /> : null}
            {toOaiy ? null : <VoiceCard />}
            {toOaiy ? null : <ServicesCard />}
            <BackgroundAiCard />
            {toOaiy ? null : <AudioCard />}
            <WaitingCard />
            <ScreeningCard />
            {toOaiy ? null : <AdvancedCard />}
            <SaveBar />
          </>
        )}
      </div>
    </div>
  );
}

// Kick the load exactly where the original called wire(); a notify landing
// before the component subscribes is replayed by the store on subscribe.
void loadAll();

render(<App />, document.getElementById('root')!);

// State + actions for the sandboxed Receptionist Settings console - the
// behavior-preserving port of the embedded-string screen's IIFE state machine.
// Rendering is preact (index.tsx + components/*): wherever the original
// repainted raw markup this store notifies the subscriber instead; every code
// path, payload shape, validation and gating rule is otherwise unchanged.
//
// SECURITY-CRITICAL invariants preserved from the reviewed original (each was
// a review defect fix - regressing any is a real incident):
//  - MANAGER PIN IS WRITE-ONLY: never seeded from settings.get (only the
//    managerPinSet boolean is read), sent ONLY when the operator typed a new
//    one (blank on save = KEEP), cleared ONLY via the explicit removePin.
//  - PARTIAL SAVES NEVER CLOBBER THE DIRTY BASELINE: each save handler rebases
//    ONLY the keys it actually persisted into state.saved (a first-save create
//    persists the whole draft; later saves their own keys only), so pending
//    edits in other cards are never silently marked saved and lost.
//  - CREATE-IN-FLIGHT GUARD: the settings record is a singleton created on
//    first save; concurrent first-saves share ONE create (createInFlight) and
//    the create sends the FULL draft (create validates required fields and
//    does not merge). Later saves are PARTIAL updateRecord patches (the
//    controller PATCH-merges).
import {
  AI_GATEWAY_BASE,
  composeAgentPayload,
  DEFAULT_PERSONA,
  liveRoute,
  type Draft,
  type LiveRoute,
  type SourceService,
} from './agentPayload';
import {
  baseName,
  boolish,
  normalizeEngine,
  parseCatalog,
  rec,
  splitList,
  str,
  voiceMatchesEngine,
  voiceUsableByEngine,
  type CatalogEngine,
} from './helpers';

// -- state shapes --

/** One entry of FormLogic.aiSources() (the host-resolved desktop listing).
 *  Cast, not normalized: the original consumed the raw entries directly. */
export interface AiSource {
  kind: string;
  id: string;
  refId: string;
  name: string;
  category: string;
  status: string;
  url: string;
  capabilities: string[];
  enabled?: boolean;
  model?: string;
}

export interface RunningInfo {
  greeting: string;
  persona: string;
  voice: string;
  model: string;
  aiReceptionist: boolean;
  /** Where the SAVED Aokie settings send calls (the plugin applies a route
   *  change when it next starts). */
  route: LiveRoute;
  voiceMode: 'flow' | 'standard' | 'desktop_realtime' | 'oaiy';
  voiceModeLabel: string;
  providerLabel: string;
  realtimeVoice: string;
  realtimeTurnDetection: string;
  appointmentToolsLabel: string;
  agentHangup: boolean;
  configVersion: number | undefined;
}

export interface EngineState {
  loaded: boolean;
  engine: string;
  modelDir: string;
  customDir: boolean;
  /** The engine the PLUGIN is actually running, as last read/saved.
   *  `engine` is the operator's pending pick: the two differ until "Save
   *  speech engine" is pressed, and the voice push must be judged against the
   *  engine that will really speak, not the one on screen. */
  savedEngine: string;
}

export interface AudioState {
  loaded: boolean;
  sendAudio: boolean;
  audioTranscript: boolean;
}

export interface WaitingState {
  loaded: boolean;
  holdAndCallWaiting: boolean;
  autoHoldQueue: boolean;
  autoConnectPhone: boolean;
}

export interface ScreeningState {
  loaded: boolean;
  recordLoaded: boolean;
  blockedNumbers: string;
  acceptPattern: string;
  rejectPrivate: boolean;
  screenMessage: string;
  blockedMessage: string;
  autoBlockAbuse: boolean;
  managerNumbers: string;
  /** WRITE-ONLY staging for a NEWLY TYPED pin - never seeded from the plugin. */
  managerPin: string;
  managerPinSet: boolean;
  whitelistOnly: boolean;
  /** The outbound-SMS kill switch (record field `sms_enabled`). Held here
   *  rather than on the draft because it is a policy field this card saves,
   *  like whitelistOnly - the agent payload never carries it. */
  smsEnabled: boolean;
  defaultCountryCode: string;
}

export interface BusyFlags {
  engine?: boolean;
  audio?: boolean;
  waiting?: boolean;
  screening?: boolean;
  save?: boolean;
  apply?: boolean;
}

/** The linked desktop, as the owner's registry last saw it (null = unknown:
 *  a member cannot read the registry, or there is no linked desktop). */
export interface DesktopSeen {
  deviceName: string;
  lastSeenAt: string | null;
}

/** What OAIY reports about itself through its AI gateway's source list
 *  (FormLogic.aiSources): its call voice service and its provider's model.
 *  Empty strings = not reported (an older OAIY, or no listing here). */
export interface OaiyReport {
  voiceStatus: string;
  model: string;
}

/** The outcome of the last push to Aokie that the operator should see:
 *  ok, a step still to take (restart, consent), or not applied at all. */
export interface ApplyNote {
  tone: 'ok' | 'warn' | 'bad';
  text: string;
}

export interface ScreenState {
  presence: { kind: string };
  demo: boolean;
  canGet: boolean;
  canSet: boolean;
  mayWrite: boolean;
  draft: Draft | null;
  saved: Draft | null;
  recordId: string | null;
  running: RunningInfo | null;
  runningError: string | null;
  runningRefreshing: boolean;
  err: string | null;
  aiSources: AiSource[] | null;
  catalog: CatalogEngine[] | null;
  engine: EngineState;
  audio: AudioState;
  waiting: WaitingState;
  screening: ScreeningState;
  showAdvanced: boolean;
  busy: BusyFlags;
  /** The raw live settings bag from the last good settings.get (null = none). */
  live: Record<string, unknown> | null;
  /** The record had no route and Aokie already sends calls to OAIY: the draft
   *  now says so, pending a save that records it for the follow-ups. */
  routeAdopted: boolean;
  /** The other-routes disclosure in the route card. */
  showOtherRoutes: boolean;
  desktop: DesktopSeen | null;
  applyNote: ApplyNote | null;
}

