  business_name: '',
  instructions: '',
  business_info: '',
  greeting: '',
  model: '',
  llm_endpoint: '',
  stt_endpoint: '',
  tts_endpoint: '',
  llm_source: '',
  stt_source: '',
  tts_source: '',
  correction_source: '',
  correction_endpoint: '',
  background_ai_source: '',
  background_ai_model: '',
  voice: '',
  reply_mode: 'agent',
