  demo: false,
  canGet: false,
  canSet: false,
  mayWrite: false,
  draft: null,
  saved: null,
  recordId: null,
  running: null,
  runningError: null,
  runningRefreshing: false,
  err: null,
  aiSources: null,
  catalog: null,
  engine: { loaded: false, engine: '', modelDir: '', customDir: false, savedEngine: '' },
  audio: { loaded: false, sendAudio: false, audioTranscript: false },
  waiting: { loaded: false, holdAndCallWaiting: false, autoHoldQueue: false, autoConnectPhone: true },
  screening: {
    loaded: false,
    recordLoaded: false,
    blockedNumbers: '',
    acceptPattern: '',
    rejectPrivate: false,
    screenMessage: '',
    blockedMessage: '',
    autoBlockAbuse: true,
