// Sticky save bar: dirty indicator + Discard + Save + "Save & apply now"
// (the apply button pushes the composed payload; inactive records save
// without pushing - that gate lives in the store's doSaveApply).
import { dirty, discard, doSave, doSaveApply, state } from '../store';

export function SaveBar() {
  const dis = !state.mayWrite || !!state.busy.save || !!state.busy.apply;
  const dirtyNow = dirty();
  return (
    <div class="savebar">
      <div class="inner">
        {dirtyNow ? <span class="dirty">Unsaved changes</span> : <span class="clean">Saved</span>}
        <div class="right">
          {dirtyNow ? (
            <button type="button" class="btn sm" data-act="discard" onClick={discard}>Discard</button>
          ) : null}
          <button type="button" class="btn" data-act="save" disabled={dis || !dirtyNow} onClick={doSave}>
            {state.busy.save ? 'Saving...' : 'Save'}
          </button>
          {state.canSet ? (
            <button type="button" class="btn primary" data-act="save-apply" disabled={dis} onClick={doSaveApply}>
              {state.busy.apply ? 'Applying...' : 'Save & apply now'}
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
}

/* Aokie Receptionist - the one stylesheet every pack screen shares (shipped as
   aokie.css ahead of each screen's own styles.css). Token-only (--fl-* from
   the host palette, so it follows the app accent and flips light/dark) and
   sized like FormLogic's screen kit (formlogic/kit): 14px cards, 11px
   uppercase card titles, 13px buttons and 9px control radii. Each screen's
   root carries the .ak class; its own stylesheet adds layout only. */

.ak { color: var(--fl-text); font-size: 13.5px; line-height: 1.5; -webkit-font-smoothing: antialiased; }
.ak *, .ak *::before, .ak *::after { box-sizing: border-box; }
.ak p { margin: 0; overflow-wrap: break-word; }
.ak p + p { margin-top: 8px; }

/* -- type ---------------------------------------------------------------- */
.ak .page-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 6px 12px; padding: 2px 2px 0; }
.ak h1 { margin: 0; font-size: 18px; font-weight: 650; letter-spacing: -0.015em; line-height: 1.25; }
.ak .page-head .sub { margin: 2px 0 0; flex-basis: 100%; font-size: 12.5px; color: var(--fl-muted); }
.ak h2 { margin: 0 0 10px; font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--fl-muted); }
.ak h3 { margin: 16px 0 6px; font-size: 12.5px; font-weight: 600; color: var(--fl-text); }
.ak .muted { color: var(--fl-muted); font-size: 12.5px; }
.ak .faint { color: var(--fl-faint); font-size: 12px; }
.ak .hint { display: block; margin: 5px 0 0; font-size: 11.5px; line-height: 1.5; color: var(--fl-faint); }
.ak .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; }
.ak strong { font-weight: 600; }

/* -- cards --------------------------------------------------------------- */
.ak .card { background: var(--fl-surface); border: 1px solid var(--fl-border); border-radius: 14px; padding: 16px 18px; box-shadow: var(--fl-shadow); min-width: 0; }
.ak .card > .muted:first-of-type { margin-bottom: 4px; }
.ak .hdr, .ak .sectionrow { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; margin-bottom: 10px; }
.ak .hdr h2, .ak .sectionrow h2 { margin: 0; }
.ak .actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 14px; }
.ak .divided { margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--fl-border); }
.ak .footnote { margin-top: 12px; }

/* -- buttons ------------------------------------------------------------- */
.ak .btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 34px; padding: 7px 14px; border-radius: 9px;
  border: 1px solid var(--fl-border); background: var(--fl-surface); color: var(--fl-text); font: inherit; font-size: 13px; font-weight: 600;
  line-height: 1.2; cursor: pointer; white-space: nowrap; text-decoration: none;
  transition: background 0.15s ease, border-color 0.15s ease, filter 0.15s ease, opacity 0.15s ease; }
.ak .btn:hover:not(:disabled) { background: var(--fl-surface-2); border-color: color-mix(in srgb, var(--fl-accent) 45%, var(--fl-border)); }
.ak .btn:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; }
.ak .btn:disabled, .ak .btn[disabled] { opacity: 0.5; cursor: not-allowed; }
.ak .btn.sm { min-height: 28px; padding: 4px 11px; font-size: 12px; border-radius: 8px; }
.ak .btn.primary { background: var(--fl-accent); border-color: var(--fl-accent); color: var(--fl-accent-contrast); }
.ak .btn.primary:hover:not(:disabled) { background: var(--fl-accent); border-color: var(--fl-accent); filter: brightness(1.07); }
.ak .btn.danger { color: var(--fl-bad); border-color: color-mix(in srgb, var(--fl-bad) 55%, var(--fl-border)); }
.ak .btn.danger:hover:not(:disabled) { background: color-mix(in srgb, var(--fl-bad) 8%, transparent); border-color: var(--fl-bad); }
.ak .btn.danger.solid { background: var(--fl-bad); border-color: var(--fl-bad); color: var(--fl-accent-contrast); }

/* -- pills and dots ------------------------------------------------------ */
.ak .pill { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; padding: 2px 10px; font-size: 11px; font-weight: 600;
  line-height: 1.6; white-space: nowrap; color: var(--fl-muted); background: var(--fl-surface-2); border: 1px solid var(--fl-border); }
.ak .pill.ok { color: var(--fl-good); border-color: color-mix(in srgb, var(--fl-good) 40%, transparent); background: color-mix(in srgb, var(--fl-good) 10%, transparent); }
.ak .pill.warn { color: var(--fl-warn); border-color: color-mix(in srgb, var(--fl-warn) 40%, transparent); background: color-mix(in srgb, var(--fl-warn) 10%, transparent); }
.ak .pill.bad { color: var(--fl-bad); border-color: color-mix(in srgb, var(--fl-bad) 40%, transparent); background: color-mix(in srgb, var(--fl-bad) 10%, transparent); }
