.ak .notice > span, .ak .notice > strong { flex: 1 1 260px; min-width: 0; }
.ak .notice strong { display: block; flex-basis: 100%; }
.ak .notice .btn { flex: none; }
.ak .notice.ok { border-left-color: var(--fl-good); background: color-mix(in srgb, var(--fl-good) 7%, var(--fl-surface)); }
.ak .notice.warn { border-left-color: var(--fl-warn); background: color-mix(in srgb, var(--fl-warn) 8%, var(--fl-surface)); }
.ak .notice.bad { border-left-color: var(--fl-bad); background: color-mix(in srgb, var(--fl-bad) 7%, var(--fl-surface)); }
.ak .banner { border: 1px solid color-mix(in srgb, var(--fl-bad) 45%, var(--fl-border)); border-left: 3px solid var(--fl-bad); border-radius: 10px; padding: 10px 14px;
  font-size: 13px; color: var(--fl-bad); background: color-mix(in srgb, var(--fl-bad) 6%, var(--fl-surface)); overflow-wrap: break-word; }

/* -- facts: label / value rows ------------------------------------------ */
.ak dl.facts { margin: 4px 0 0; }
.ak dl.facts > div { display: grid; grid-template-columns: minmax(118px, 32%) minmax(0, 1fr); gap: 3px 14px; align-items: baseline;
  padding: 8px 0; border-top: 1px solid var(--fl-border); }
.ak dl.facts > div:first-child { border-top: 0; padding-top: 2px; }
.ak dl.facts dt { font-size: 12px; color: var(--fl-muted); }
