  transition: border-color 0.15s ease, box-shadow 0.15s ease; }
.ak input[type="text"]:focus, .ak input[type="password"]:focus, .ak textarea:focus, .ak select:focus {
  outline: none; border-color: var(--fl-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--fl-accent) 18%, transparent); }
