(function () {
  var phone = String(inputs.callerPhone || inputs.from || '');
  // The customers node pre-filters with the phone_eq op (digits-only last-9
  // suffix, matched in the DATABASE - so '+61 400 000 000' matches
  // '+61400000000' and the lookup works at any customer count, no 200-row
  // scan). Whatever came back IS the match set; take the first.
  var custNode = nodes.customers || {};
  var hit = custNode.first || ((custNode.responses || [])[0] || null);
  var name = hit ? String((hit.answers || {}).name || '') : '';
  return {
    found: !!hit,
    customerId: hit ? hit.id : null,
    name: name,
    greeting: hit
      ? 'Hi ' + name + ', thanks for calling back. Are you calling about your last booking or something new?'
      : 'Thanks for calling. How can I help you today?'
  };
})()

(function () {
  // formlogic_list_responses returns the array directly on the desktop f2i runner
  // (nodes.settings) but {responses:[...]} in the TS executor — handle both.
  var node = nodes.settings;
  var rows = node && node.responses ? node.responses : (Array.isArray(node) ? node : []);
  var cfg = {};
  for (var i = 0; i < rows.length; i++) {
    var a = (rows[i] && rows[i].answers) || {};
    if (String(a.active || 'yes') !== 'no') { cfg = a; break; }
  }
  var route = String(cfg.call_route || '').trim();
  var toOaiy = route === 'oaiy';
  var persona = String(cfg.instructions || '').trim() || "A small business answers this phone. People call to ask a question, to book a time, or to leave a message for the team. Bookings made on a call are requests: someone from the team confirms each one with the caller afterwards. When someone needs a call back, the team needs their name, what it is about, and a good number and time to reach them.";
  var business = String(cfg.business_name || '').trim();
  if (business) persona = 'You are the phone receptionist for ' + business + '.' + (persona ? '\n' + persona : '');

  var info = String(cfg.business_info || '').trim().slice(0, 4000);
  if (info) {
    persona += (persona ? '\n\n' : '') + 'BUSINESS INFO - the ONLY facts about the business you may share:\n' + info
      + '\nAnswer questions about services, menu, prices, opening hours or policies ONLY from this info, quoting details exactly. If something is not covered here, say you will have the team confirm it - NEVER invent business details.';
  }
  var greeting = String(cfg.greeting || '').trim();
  if (!greeting) {
    greeting = business
      ? 'Thank you for calling ' + business + '! How can I help you today?'
      : 'Thanks for calling! How can I help you today?';
  }
  if (toOaiy) {
    return {
      callRoute: 'oaiy',
      persona: persona,
      greeting: greeting,
      aiReceptionist: true,
      settingsPayload: {
        persona: persona,
        greeting: greeting,
        aiReceptionist: true,
        realtimeVoiceMode: 'desktop_realtime',
        realtimeVoiceEndpoint: 'ws://127.0.0.1:17872/api/ai/providers/oaiy/v1/realtime/stream',
        realtimeVoiceDestination: 'https://oaiy.localhost'
      }
    };
  }
  var replyMode = String(cfg.reply_mode || '').trim();
  // Source picks (CON-302 / SRC-203): resolve per call, against the LIVE
  // desktop services list (nodes.svc), so a port change self-heals on the
  // next call.
  // 'service:<id>' -> the running service's loopback URL + the lane's
  // conventional path ('' when not running: the plugin then falls back to
  // auto-detect / its built-in engine, which is where a dead URL would have
  // ended up anyway, minus the timeout).
  // 'provider:<id>' (chat and transcription lanes) -> the desktop AI gateway's
  // per-provider
  // OpenAI base (http://127.0.0.1:17872/api/ai/providers/<id> + the lane
  // path — the gateway's routes are /api/ai/providers/:id/v1/chat/completions
  // and .../v1/models, which is exactly what the plugin's LlmClient derives
  // from a chat URL). The gateway port is FIXED, so this composes with NO
  // service lookup — emitted even when the desktop_services node lists
  // nothing. Transcription provider picks use the gateway's multipart route;
  // Desktop injects the configured model and credential. TTS provider picks
  // still resolve to '' (plugin default) until audio/speech is exposed.
  // 'custom' or blank -> the legacy endpoint field. On the LLM lane only, a
  // completely blank source + endpoint preserves an explicit Desktop/plugin
  // choice; an explicit custom/service/provider pick still applies.
  var svcNode = nodes.svc || {};
  var svcList = svcNode.services || [];
  function laneUrl(source, customUrl, path, providerOk, preserveBlank) {
    source = String(source || '').trim();
    var custom = String(customUrl || '').trim();
    if (!source) return preserveBlank && !custom ? undefined : custom;
    if (source === 'custom') return custom;
    if (source.indexOf('service:') === 0) {
      var sid = source.slice(8);
      for (var i = 0; i < svcList.length; i++) {
        if (svcList[i] && svcList[i].id === sid && svcList[i].url) return svcList[i].url + path;
      }
      return '';
    }
    if (source.indexOf('provider:') === 0) {
      if (!providerOk) return '';
      return 'http://127.0.0.1:17872/api/ai/providers/' + encodeURIComponent(source.slice(9)) + path;
    }
    return custom;
  }
  var voice = String(cfg.voice || '').trim();
  var model = String(cfg.model || '').trim();
  var applyAiEndpoint = String(cfg.llm_source || '').trim() !== '' || String(cfg.llm_endpoint || '').trim() !== '';
  var applyAiModel = applyAiEndpoint || model !== '';
  var aiEndpoint = laneUrl(cfg.llm_source, cfg.llm_endpoint, '/v1/chat/completions', true, true);
  // Desktop injects the selected transcription provider profile's model and
  // credential into the plugin's multipart request. TTS stays gated below.
  var sttEndpoint = laneUrl(cfg.stt_source, cfg.stt_endpoint, '/v1/audio/transcriptions', true, false);
  var ttsEndpoint = laneUrl(cfg.tts_source, cfg.tts_endpoint, '/v1/audio/speech', false, false);
  var correctionEndpoint = laneUrl(cfg.correction_source, cfg.correction_endpoint, '/v1/chat/completions', true, false);
  // connector_request accepts a selector for its WHOLE payload. Build that
  // object here so absent keys stay absent in both the TS and Rust runners;
  // resolving an undefined field inside a static payload would become null in
  // the Rust runner and overwrite the plugin setting.
  var settingsPayload = {
    persona: persona,
    greeting: greeting,
    ttsVoice: voice,
    sttEndpoint: sttEndpoint,
    ttsEndpoint: ttsEndpoint,
    audioTranscriptEndpoint: correctionEndpoint,
    aiReceptionist: replyMode !== 'flow'
  };
  if (applyAiEndpoint) settingsPayload.aiEndpoint = aiEndpoint;
  if (applyAiModel) settingsPayload.aiModel = model;
  if (route === 'aokie') settingsPayload.realtimeVoiceMode = 'legacy';
  return {
    callRoute: route,
    persona: persona,
    greeting: greeting,
    voice: voice,
    model: model,
    // AI plumbing, all flow-configurable: blank = the plugin's default behaviour
    // (LLM auto-detect :8080/:11434; built-in on-device STT/TTS engines).
    aiEndpoint: aiEndpoint,
    applyAiEndpoint: applyAiEndpoint,
    applyAiModel: applyAiModel,
    sttEndpoint: sttEndpoint,
    ttsEndpoint: ttsEndpoint,
    // Correction lane (audioTranscript side runs): the plugin's correction
    // client is the SAME LlmClient as the reply lane, so it wants a full
    // /v1/chat/completions URL. Blank source resolves '' = corrections use
    // the main reply model; audioTranscriptModel is never pushed (the chosen
    // service owns its model).
    audioTranscriptEndpoint: correctionEndpoint,
    aiReceptionist: replyMode !== 'flow',
    settingsPayload: settingsPayload
  };
})()

(function () {
  var phone = String(inputs.from || '');
  // The customers node pre-filters with the phone_eq op (digits-only last-9
  // suffix, matched in the DATABASE) - no client-side scan, no 200-row cap.
  var custNode = nodes.customers || {};
  var hit = custNode.first || ((custNode.responses || [])[0] || null);
  // Base config: SAME composition as the Configure Receptionist flow.
  var sNode = nodes.settings;
  var sRows = sNode && sNode.responses ? sNode.responses : (Array.isArray(sNode) ? sNode : []);
  var cfg = {};
  for (var j = 0; j < sRows.length; j++) {
    var sa = (sRows[j] && sRows[j].answers) || {};
