})()

data.prompt:
Today is {{nodes.ctx.today}}.

{{nodes.ctx.llmContext}}

Return ONLY this JSON:
{"action": "confirm" | "cancel" | "move" | "block" | "query" | "none", "target_date": "YYYY-MM-DD" or null, "target_time": "HH:MM" or null, "target_name": string or null, "new_date": "YYYY-MM-DD" or null, "new_time": "HH:MM" or null, "block_number": string or null}

Rules: "confirm" / "cancel" / "move" act on ONE existing booking from the list - set "target_date" to that booking's EXISTING date (resolve relative wording like "Friday" or "tomorrow" from today's date), and fill "target_time"/"target_name" only when the manager said them; for "move", "new_date"/"new_time" are the NEW slot in YYYY-MM-DD / 24-hour HH:MM (only the parts the manager gave); "block" is for blocking a phone number - put the digits they said in "block_number"; "query" is the manager ASKING what is booked (list the appointments, who is booked in, what do I have) - set "target_date" ONLY when they asked about one specific day; anything else (greetings, unclear speech) is "none". Use null when unsure - never guess.

data.expr:
(function () {
  var c = nodes.ctx || {};
  var out = { ok: false, spoken: '', summary: '', hasUpdate: false, updateId: '', update: {}, hasBlock: false, blockNumber: '' };
  if (c.hasRequest !== true) {
    out.spoken = 'I did not catch the change you want - say it again?';
    return out;
  }
  var raw = String((typeof nodes.decide === 'string' ? nodes.decide : (nodes.decide || {}).content) || '').trim();
  var m = raw.match(/\{[\s\S]*\}/);
  var data = {};
  try { data = JSON.parse(m ? m[0] : raw) || {}; } catch (e) { data = {}; }
  var action = String(data.action || 'none').toLowerCase();
  if (['confirm', 'cancel', 'move', 'block', 'query', 'none'].indexOf(action) === -1) action = 'none';
  if (action === 'none') {
    out.spoken = 'I could not map that to a change or a calendar question. You can ask what is booked, confirm, move or cancel a booking, or block a number - say it again with the full date?';
    return out;
  }
  if (action === 'block') {
    var num = String(data.block_number || '').replace(/[^0-9+]/g, '');
    if (num.replace(/\D+/g, '').length < 6) {
      out.spoken = 'Which number should I block? Say the full number.';
      return out;
    }
    out.ok = true;
    out.hasBlock = true;
    out.blockNumber = num;
    out.summary = 'Manager blocked ' + num + '.';
    out.spoken = 'Done - that number is now blocked.';
    return out;
  }
  var DAYFULL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var MONFULL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  var nowD = new Date();
  function dayLabel(dStr) {
    var hp = dStr.split('-');
    var dt = new Date(Number(hp[0]), Number(hp[1]) - 1, Number(hp[2]));
    var label = DAYFULL[dt.getDay()] + ' ' + dt.getDate() + ' ' + MONFULL[dt.getMonth()];
    if (dt.getFullYear() !== nowD.getFullYear()) label += ' ' + dt.getFullYear();
    return label;
  }
  function t12(tStr) {
    if (!/^\d{2}:\d{2}$/.test(tStr)) return '';
    var th = Number(tStr.slice(0, 2));
    var h = th % 12 === 0 ? 12 : th % 12;
    return h + (tStr.slice(3, 5) === '00' ? '' : ':' + tStr.slice(3, 5)) + ' ' + (th >= 12 ? 'PM' : 'AM');
  }
  function realIso(dStr) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dStr)) return false;
    var dp = dStr.split('-');
    var dObj = new Date(Number(dp[0]), Number(dp[1]) - 1, Number(dp[2]));
    return dObj.getFullYear() === Number(dp[0]) && (dObj.getMonth() + 1) === Number(dp[1]) && dObj.getDate() === Number(dp[2]);
  }
  function validClock(tStr) {
    return /^\d{2}:\d{2}$/.test(tStr) && Number(tStr.slice(0, 2)) <= 23 && Number(tStr.slice(3, 5)) <= 59;
  }
  function apptLabel(ap) {
    return ap.service + ' on ' + dayLabel(ap.date) + (ap.time && t12(ap.time) ? ' at ' + t12(ap.time) : '') + (ap.name ? ' for ' + ap.name : '');
  }
  var appts = Array.isArray(c.appts) ? c.appts : [];
  // QUERY (manager read, 2026-07-17 - live call 085ce239: 'look up what
  // appointments I have booked' hit the change-only refusal): a PIN-verified
  // manager asking what is booked gets the upcoming list, names included,
  // composed FROM RECORDS - never model prose. target_date narrows to a day.
  if (action === 'query') {
    var qd = String(data.target_date || '').trim().slice(0, 10);
    var qDay = realIso(qd);
    var rows = [];
    for (var qr = 0; qr < appts.length; qr++) {
      if (String(appts[qr].status || '') === 'cancelled') continue;
      if (qDay && String(appts[qr].date || '') !== qd) continue;
      rows.push(appts[qr]);
    }
    rows.sort(function (x, y) {
      var a = String(x.date || '') + ' ' + String(x.time || '');
      var b = String(y.date || '') + ' ' + String(y.time || '');
      return a < b ? -1 : a > b ? 1 : 0;
    });
    out.ok = true;
    if (!rows.length) {
      out.spoken = qDay ? 'Nothing is booked on ' + dayLabel(qd) + '.' : 'There are no upcoming bookings on the calendar.';
      return out;
    }
    var MAXQ = 8;
    var parts = [];
    for (var qp = 0; qp < rows.length && qp < MAXQ; qp++) {
      parts.push(apptLabel(rows[qp]) + ' (' + String(rows[qp].status || 'requested') + ')');
    }
    var head = qDay
      ? dayLabel(qd) + ' has ' + rows.length + ' booking' + (rows.length === 1 ? '' : 's') + ': '
      : (rows.length === 1 ? 'There is 1 upcoming booking: ' : 'There are ' + rows.length + ' upcoming bookings: ');
    out.spoken = head + parts.join('; ') + (rows.length > MAXQ ? '; and ' + (rows.length - MAXQ) + ' more.' : '.');
    return out;
  }
